window.JASTROW_CHUNKS[1018]={"39712":{"h":"כְּלוֹמַר","r":"KRU09441","alt":[],"source":"krupnik","glosses":[{"text":"that is to say, this means","label":""}],"html":"<p>זאת אומרת that is to say, this means  ב״ר פס״ה: חזיר הזה בשעה שהוא רובץ מפשיט את טלפיו כלומר שאני טהור.</p>","notation":["מה״ח"]},"39713":{"h":"כְּלוֹנָס","r":"KRU09443","alt":["כְּלוֹנְסָא"],"source":"krupnik","glosses":[{"text":"beam, pole","label":""}],"html":"<p>מוט beam, pole  ב״ב ס״ז ע״ב: כלונסות של ארז; תרג׳ יב״ע במ׳ ל״ה כ׳: טלק עלוי כלונסן.</p>","notation":[]},"39714":{"h":"כְּלוּסִין","r":"KRU09445","alt":[],"source":"krupnik","glosses":[{"text":"licorice (bot.)","label":""}],"html":"<p>מין אילן licorice (bot.)  ירוש׳ מעש׳ פ״ב נ׳ ע״א: היה עושה בכלוסין וכו׳.</p>","notation":["ז״ר"]},"39715":{"h":"כְּלוּפְסִין","r":"KRU09446","alt":[],"source":"krupnik","glosses":[{"text":"a species of figs","label":""}],"html":"<p>מין תאנים a species of figs  נדר׳ נ׳ ע״ב: היה עושה בכלופסין.</p>","notation":["ז״ר"]},"39716":{"h":"כְּלֵי","r":"KRU09447","alt":[],"source":"krupnik","glosses":[{"text":"to be finished","label":""}],"html":"<p>נגמר to be finished  ב״מ ע״ט ע״א: וקא כליא קרנא.</p>","notation":["פ״ע"]},"39717":{"h":"כַּלֵי","r":"KRU09448","alt":[],"source":"krupnik","glosses":[{"text":"to destroy","label":""},{"text":"to call, to roar","label":""},{"text":"to restrain","label":""},{"text":"to be withheld","label":""}],"html":"<p>איבד to destroy  ב״ק ג׳ ע״א: דמכליא קרנא. אַכְלֵי  אפ׳, 1) שאג to call, to roar  תרג׳ יואל ד׳ ט״ו (מציון ישאג): מציון יכלי. 2) עצר to restrain  תרג׳ דהי״ב ז׳ י״ג (אעצור השמים): אכלי שמיא. אִתְכְּלִי אתפ׳, נעצר to be withheld  תרג׳ בר׳ ח׳ ב׳ (ויכלא הגשם): ואתכלי מטרא. </p>","notation":["פַעל"]},"39718":{"h":"כְּלִי כְּלִי אוּמָנוּת","r":"KRU09449","alt":[],"source":"krupnik","glosses":[{"text":"tool","label":""}],"html":"<p>כלי מלאכה ועבודה tool  ב״ר פ״א: התורה אומרת אני הייתי כלי אומנותו של הקב״ה.</p>","notation":["Marked biblical in source"]},"39719":{"h":"כְּלֵי זַיִין","r":"KRU09450","alt":[],"source":"krupnik","glosses":[{"text":"armour","label":""}],"html":"<p>נשק armour  יב׳ קט״ו ע״א: אשה כלי זיינה עליה.</p>","notation":[]},"39720":{"h":"כְּלֵי לָבָן","r":"KRU09451","alt":[],"source":"krupnik","glosses":[{"text":"white garments","label":""}],"html":"<p>בגדים לבנים white garments  תענ׳ פ״ד מ״ח: לא היו ימים טובים לישראל כט״ו באב וכיוה״כ שבהן בנות ישראל יוצאות בכלי לבן וכו׳.</p>","notation":[]},"39721":{"h":"כְּלֵי פִשְׁתָּן","r":"KRU09452","alt":[],"source":"krupnik","glosses":[{"text":"linen garments","label":""}],"html":"<p>בגדי בד linen garments  ב״ק פ״י מ״ט: לוקחין מן הנשים כלי צמר ביהודה וכלי פשתן בגליל.</p>","notation":[]},"39722":{"h":"כְּלִי צוּרָה","r":"KRU09453","alt":[],"source":"krupnik","glosses":[{"text":"earthen vessel","label":""}],"html":"<p>כלי חרס, כלי יוצר earthen vessel  ירוש׳ שבת פ״ז י׳ ע״ד: הגודל כלי צורה והנופח כלי זכוכית.</p>","notation":[]},"39723":{"h":"כֵּלִים","r":"KRU09454","alt":[],"source":"krupnik","glosses":[{"text":"name of a treatise of the Mishna","label":""}],"html":"<p>שם מסכת בסדר טהרות name of a treatise of the Mishna  ויק״ר פי״ט: מי יכול ללמוד את כל התורה וכו׳ כלים ל׳ פרקים.</p>","notation":[]},"39724":{"h":"כֵּלִים שְׁחוֹרִים","r":"KRU09456","alt":[],"source":"krupnik","glosses":[{"text":"black garments","label":""}],"html":"<p>בגדים שחורים black garments  שבת קי״ד ע״א: אל תקברוני לא בכלים לבנים ולא בכלים שחורים.</p>","notation":[]},"39725":{"h":"כַּלִּיד","r":"KRU09459","alt":["כַּלִּידָא"],"source":"krupnik","glosses":[{"text":"cup","label":"1"},{"text":"calyx of flowers","label":"2"}],"html":"<p>1 כוס cup  תרג׳ בר׳ מ״ד י״ב (וימצא הגביע): ואשתכח כלידא.\n2 בוס הפרח calyx of flowers  תרג׳ שמ׳ כ״ה ל״ג (ושלשה גביעים משקדים): תלתא כלידין מציירין.</p>","notation":[]},"39726":{"h":"כְּלִיבָה","r":"KRU09460","alt":[],"source":"krupnik","glosses":[{"text":"box","label":"1"},{"text":"bier","label":"2"}],"html":"<p>1 ארון, ארגז box  איכ״ר פתיחתא: ומצאו שם שני כרובים נטלו אותן והחזירון לכליבה.\n2 מטה שנושאים בה את המת bier  פרה פי״ב מ״ט: ומטה של טרבל וקרן של כליבה.</p>","notation":["נ׳"]},"39727":{"h":"כְּלִידָרִין","r":"KRU09461","alt":[],"source":"krupnik","glosses":[{"text":"jewels","label":""}],"html":"<p>תכשיטים jewels  ב״ר פ״ט ז׳: שאין עבד וכו׳ לובש כלידרין.</p>","notation":["ז״ר"]},"39728":{"h":"כְּלָיָה","r":"KRU09463","alt":[],"source":"krupnik","glosses":[{"text":"extinction","label":""}],"html":"<p>איבוד והשמדה extinction  אבות פ״ה מ״ח: רעב של כליה.</p>","notation":["נ׳"]},"39729":{"h":"כִּלְיוּתָא","r":"KRU09465","alt":[],"source":"krupnik","glosses":[{"text":"hope","label":""}],"html":"<p>תקוה hope  תרג׳ תה׳ קי״ט קט״ז (משברי): מן כליותי.</p>","notation":["נ׳"]},"39730":{"h":"כַּלַּיָּיא","r":"KRU09466","alt":["כַּלַּיָּיה"],"source":"krupnik","glosses":[{"text":"brides","label":""}],"html":"<p>כלות brides  ירוש׳ פאה פ״א ט״ו ע״ד: והוה מקלס קומי כלייא (ע״ז פ״ג מ״ב ע״ג: בלייה).</p>","notation":[]},"39731":{"h":"כְּלִיל","r":"KRU09469","alt":["כְּלִילָא"],"source":"krupnik","glosses":[{"text":"wreath, crown","label":"1"},{"text":"coronation","label":"2"}],"html":"<p>1 זֵר, נזר wreath, crown  ירוש׳ מעש״ש פ״ד נ״ה ע״ב: כליל דזית; שבת קנ״ב ע״א: כלילא דורדא.\n2 התקסרות, עליה על כסא המלכות coronation  ב״ב ח׳ ע״א: דמי כלילא.</p>","notation":[]},"39732":{"h":"כְּלִיל מַלְכָּא","r":"KRU09470","alt":[],"source":"krupnik","glosses":[{"text":"melilot","label":""}],"html":"<p>מין צמח melilot  שבת ק״ט ע״ב: חד כליל מלכא.</p>","notation":[]},"39733":{"h":"כָּלִינוֹס","r":"KRU09472","alt":[],"source":"krupnik","glosses":[{"text":"bridle","label":""}],"html":"<p>רסן bridle  תוס׳ כל׳ ב״מ ד׳ ז׳: שלשלת שעשאה אפרומביא טמאה מפני שהיא ככלינוס.</p>","notation":["ז׳"]},"39734":{"h":"כְּלִינִידִין","r":"KRU09473","alt":[],"source":"krupnik","glosses":[{"text":"a mantle","label":""}],"html":"<p>מעיל עליון a mantle  ירוש׳ סנה׳ פ״י כ״ט ע״א: הדין זונרא והדין כלינידין.</p>","notation":["ז׳"]},"39735":{"h":"כְּלִיסִים","r":"KRU09475","alt":[],"source":"krupnik","glosses":[{"text":"liqorice (bot.)","label":""}],"html":"<p>liqorice (bot.)  תר׳ פי״א מ״ד: כליסים וחרובים. </p>","notation":["ז״ר"]},"39736":{"h":"כליסריקים","r":"KRU09476","alt":["כלירכין","כלירקין"],"source":"krupnik","glosses":[{"text":"chiliarchs, commanders of one thousand soldiers","label":""}],"html":"<p>שרי אלף chiliarchs, commanders of one thousand soldiers  ספרי דב׳ (הוצ׳ מא״ש) שי״ז: כרים אלו כליסריקים שלהם (ילק׳ שם תתקמ״ד: כלירקין; קהל״ר י״ב ז׳: כלירכין).</p>","notation":[]},"39737":{"h":"כְּלֵיתָא","r":"KRU09477","alt":[],"source":"krupnik","glosses":[{"text":"wrath","label":""}],"html":"<p>כעס wrath  תרג׳ יב״ע דב׳ כ״ט (באפו ובחמתו): ברוגזיה ובכליתיה.</p>","notation":["נ׳"]},"39738":{"h":"כַּלָּךְ","r":"KRU09478","alt":[],"source":"krupnik","glosses":[{"text":"a woolly substance","label":""}],"html":"<p>מין צמר a woolly substance  מנח׳ ל״ט ע״ב: השיראין והכלך והסירקין כולם חייבים בציצית.</p>","notation":["ז׳"]},"39739":{"h":"כְּלַךְ","r":"KRU09479","alt":[],"source":"krupnik","glosses":[{"text":"cease and turn! go!","label":""}],"html":"<p>צווי, לך לך cease and turn! go!  ב״ב קס״ד ע״ב: כלך מלשון הרע.</p>","notation":[]},"39740":{"h":"כִּלְכּוּל","r":"KRU09480","alt":[],"source":"krupnik","glosses":[{"text":"sustenance","label":"1"},{"text":"temple hair","label":"2"}],"html":"<p>1 כלכלה והזנה sustenance  ספר׳ דב׳ ל״ח: מה כלכול האמור להלן בשני רעבון הכתוב מדבר וכו׳.\n2 שערות הצומחות על הרקות temple hair  שבת פ״ח מ״ד: כדי לעשות כלכול.</p>","notation":["ז׳"]},"39741":{"h":"כַּלְכִּיד","r":"KRU09481","alt":[],"source":"krupnik","glosses":[{"text":"a fish","label":""}],"html":"<p>מין דג a fish  ירוש׳ נד׳ פ״ו ל״ט ע״ג דע״ד: דגה שאיני טועם אינו אסור אלא בכלכיד.</p>","notation":["ז׳"]},"39742":{"h":"כִּלְכֵּל","r":"KRU09482","alt":[],"source":"krupnik","glosses":[{"text":"to raise a crown of hair","label":""},{"text":"to be supported","label":""}],"html":"<p>גידל שער to raise a crown of hair  נזיר פ״א מ״א: הריני מסלסל הריני מכלכל הרי עלי לשלח פרע. נִתְכַּלְכֵּל נתפ׳, ניזון ונתפרנס to be supported  פסיק״ר ד׳: ואליהו נתכלכל ע״י הצרפתית. </p>","notation":["Marked biblical in source"]},"39743":{"h":"כַּלְכָּלָה","r":"KRU09483","alt":[],"source":"krupnik","glosses":[{"text":"basket","label":"1"},{"text":"cage","label":"2"},{"text":"provision","label":"3"}],"html":"<p>1 סל basket  פאה פ״ז מ״ג: המניח את הכלכלה תחת הגפן וכו׳.\n2 כלוב cage  תוס׳ שבת י״ד ג׳: כלכלה לישב עליה תרנגולת.\n3 מזון provision  בר׳ מ״ד ע״א: על המחיה ועל הכלכלה ועל תנובת השדה.</p>","notation":["נ׳"]},"39744":{"h":"כָּלַל","r":"KRU09484","alt":[],"source":"krupnik","glosses":[{"text":"to include","label":""},{"text":"to generalize","label":""},{"text":"to be implied","label":""}],"html":"<p>1) מנה והכניס אל הכלל to include  שבוע׳ כ״ג ע״ב: בכולל דברים המותרים עם דברים האסורין. 2) קבע כלל, הכליל to generalize  ירוש׳ שבוע׳ פ״ג ל״ד ע״ג: לא סוף דבר כולל אלא אפילו פורט. נִכְלַל נפ׳, נמנה ונחשב בכלל to be implied  ירוש׳ סוטה פ״ז כ״א ע״ד: דברים שנכללו ונפרטו. </p>","notation":["Marked biblical in source"]},"39745":{"h":"כִּלֵּל","r":"KRU09485","alt":[],"source":"krupnik","glosses":[{"text":"to crown","label":"פיעל,"}],"html":"<p>פיעל, הכתיר to crown  תנח׳ ראה ז׳: אם נוצחין וכו׳ ומכללין אותו.</p>","notation":[]},"39746":{"h":"כְּלַל","r":"KRU09486","alt":[],"source":"krupnik","glosses":[{"text":"to combine","label":"2"}],"html":"<p>1 כנ״ל כִּלֵּל. תרג׳ שה״ש ג׳ י״א: דכלילו עמא וכו׳ ית מלכא. \n2 חיבר to combine  ירוש׳ מגי׳ פ״ד ע״ה ע״ב: חזרין וכללין לון.</p>","notation":["פ״י"]},"39747":{"h":"כַּלֵּל","r":"KRU09487","alt":[],"source":"krupnik","glosses":[{"text":"to be crowned","label":"אִיכַּלֵּל, אִתְכַּלֵּל התפ׳, 1"},{"text":"to marry, to be married","label":"אִיכַּלֵּל, אִתְכַּלֵּל התפ׳, 2"}],"html":"<p>פַעל, אַכְלֵל אפ׳, עי׳ כִּלֵּל. תרג׳ תה׳ ה׳ י״ג (רצון תעטרנו): רעוא תכללניה; שם ק״ג ד׳: דאכליל יתיכי חסדא. \nאִיכַּלֵּל, אִתְכַּלֵּל התפ׳, 1 הוכתר to be crowned  ב״ר פל״ד: יתכללון בי צדיקיא.\nאִיכַּלֵּל, אִתְכַּלֵּל התפ׳, 2 נכנס לחופה to marry, to be married  מגי׳ כ״ז ע״ב: כי איכלל רבה וכו׳.</p>","notation":[]},"39748":{"h":"כְּלָל","r":"KRU09488","alt":[],"source":"krupnik","glosses":[{"text":"rule, principle","label":"1"},{"text":"community","label":"2"},{"text":"generalization","label":"3"},{"text":"sum, total","label":"4"}],"html":"<p>1 חוק ועיקר rule, principle  חול׳ פ״ג מ״א: זה הכלל וכו׳.\n2 צבור community  מכי׳ בוא פסחא י״ח: ולפי שהוציא את עצמו מן הכלל וכו׳.\n3 סוג הכולל generalization  ספרא א׳: חמור או שור או שה פרט וכל בהמה לשמור כלל.\n4 סך הכל sum, total  ב״ב קכ״ג ע״א: בכללן אתה מוצא שבעים.</p>","notation":["ז׳"]},"39749":{"h":"כְּלָלָא","r":"KRU09489","alt":[],"source":"krupnik","glosses":[{"text":"by implication","label":""}],"html":"<p>כנ״ל. 1. ב״מ ק״ג ע״ב: כללא דמילתא. מִכְּלָלָא מתוך הכלל, סתם by implication  חול׳ צ״ה ע״א: הא דרב לאו בפירוש איתמר אלא מכללא איתמר. </p>","notation":["ז׳"]},"39750":{"h":"כלם","r":"KRU09490","alt":[],"source":"krupnik","glosses":[{"text":"to shame","label":"אַכְלַם אפ׳,"},{"text":"to be put to shame","label":"אִיכְּלַם, אִיתְכַּלֵּם אתפ׳,"}],"html":"<p>אַכְלַם אפ׳, הכלים ובייש to shame \nאִיכְּלַם, אִיתְכַּלֵּם אתפ׳, נכלם to be put to shame  ב״ק פ״ו ע״א: דמכלמו ליה ומיכלם; תרג׳ במ׳ י״ב י״ד (הלא תכלם): הלא תתכלם.</p>","notation":["Source marks no qal form"]},"39751":{"h":"כַּלְמֵי","r":"KRU09491","alt":[],"source":"krupnik","glosses":[{"text":"vermin","label":""}],"html":"<p>כנים vermin  בר׳ נ״א ע״ב: ממהדורי מילי ומסמרטוטי כלמי.</p>","notation":["נ״ר"]},"39752":{"h":"כְּלָנִידְיָיא","r":"KRU09492","alt":[],"source":"krupnik","glosses":[{"text":"fine cloaks for women","label":""}],"html":"<p>מין בגדי נשים fine cloaks for women  ירוש׳ שבת פ״ו ח׳ ע״ב: הרעלות – כלנידייא.</p>","notation":["ז״ר"]},"39753":{"h":"כַּלְנִיתָא","r":"KRU09493","alt":[],"source":"krupnik","glosses":[{"text":"papaver","label":""}],"html":"<p>פרג papaver  פס׳ ל״ה ע״א: קרמית – שיצניתא דמשתכחא ביני כלניתא.</p>","notation":["נ׳"]},"39754":{"h":"כְּלֵנְסָא","r":"KRU09494","alt":[],"source":"krupnik","glosses":[{"text":"pole","label":""}],"html":"<p>מוט pole  תרג׳ מל״א ז׳ ה׳ (שקף): כלנסא.</p>","notation":["ז׳"]},"39755":{"h":"כלעס","r":"KRU09495","alt":[],"source":"krupnik","glosses":[{"text":"to be choked","label":""}],"html":"<p>הקדים קנה לושט to be choked  ירוש׳ תר׳ פ״ח מ״ו ע״א: ואיתכלעסין ומיתין.</p>","notation":["פ״ע","Source emendation: בַּלְעֵס"]},"39756":{"h":"כְּלַפֵּי","r":"KRU09496","alt":[],"source":"krupnik","glosses":[{"text":"towards","label":"1"},{"text":"in relation to, with regard to","label":"2"}],"html":"<p>1 לעומת, מול towards  ירוש׳ בר׳ פ״ד ח׳ ע״ב: העומדין ומתפללין בחוצה לארץ הופכין את פניהן כלפי ארץ ישראל.\n2 ביחס אל in relation to, with regard to  ב״ב ט״ז ע״א: לא דבר איוב אלא כלפי שטן.</p>","notation":["מה״י"]},"39757":{"h":"כְּלַפֵּי לְיֵיא","r":"KRU09497","alt":[],"source":"krupnik","glosses":[{"text":"where are you turning to?","label":""}],"html":"<p>להיכן דבריך מכוונים? מה אתה סח? where are you turning to?  פסח׳ ה׳ ע״ב: כלפי לייא אמר אביי איפוך וכו׳.</p>","notation":[]},"39758":{"h":"כַּלְקִיס","r":"KRU09499","alt":[],"source":"krupnik","glosses":[{"text":"name of a place","label":""}],"html":"<p>name of a place  ירוש׳ מגי׳ פ״א ע׳ ע״ג: קמו עממיא על פליטת ספריא במדינת כלקיס ובית זבדין. </p>","notation":["שם מקום"]},"39759":{"h":"כּלְּתָא","r":"KRU09502","alt":[],"source":"krupnik","glosses":[{"text":"daughter-in-law","label":"1"},{"text":"bride","label":"2"}],"html":"<p>1 אשת הבן הבת daughter-in-law  ב״ב קמ״ג ע״ב: לא שביק בנתיה ומשדר לכלתיה. \n2 כלה, נערה ביום חתונתה bride  גיט׳ נ״ז ע״א: חתנא וכלתא.</p>","notation":["נ׳"]},"39760":{"h":"כְּמָא","r":"KRU09504","alt":[],"source":"krupnik","glosses":[{"text":"like","label":"1"},{"text":"how!","label":"2"}],"html":"<p>1 כמו like  תרג׳ יונה א׳ י״ד (כאשר חפצת): כמא דרעוא קדמך.\n2 מה״ק, עד כמה! how!  ב״ר פ״ו: כמא נפשיה דאחוה דהאי גברא מקצצא ארזין וכו׳.</p>","notation":["מה״ח"]},"39761":{"h":"כְּמַאי","r":"KRU09505","alt":[],"source":"krupnik","glosses":[{"text":"as much as","label":""}],"html":"<p>במדה ש־ as much as  יומא מ״ג ע״ב: כמאי דמסיק וכו׳.</p>","notation":["מה״ח"]},"39762":{"h":"כִּמְדוּמֶּה","r":"KRU09508","alt":[],"source":"krupnik","glosses":[{"text":"it seems","label":""}],"html":"<p>נראה הדבר it seems  מנח׳ י״ח ע״א; כמדומה אני שלא כיווננו שמועתינו.</p>","notation":[]},"39763":{"h":"כַּמָּה","r":"KRU09509","alt":[],"source":"krupnik","glosses":[{"text":"how! how many! how much!","label":"1"},{"text":"very","label":"2"}],"html":"<p>1 עד כמה! how! how many! how much!  מכי׳ משפ׳ י״ב: בוא וראה כמה חביבה מלאכה לפני מי שאמר והיה העולם שור שיש לו מלאכה משלם חמש שה שאין לו מלאכה משלם ארבע.\n2 מאד very  ירוש׳ שבת פ״ב ה׳ ע״כ: נסר שהוא מתוח מגג לגג אפילו רחב כמה אסור להלך עליו.</p>","notation":["Marked biblical in source"]},"39764":{"h":"כְּכַמָּה","r":"KRU09510","alt":[],"source":"krupnik","glosses":[{"text":"what is the charge? how much (is it)?","label":""}],"html":"<p>מהו המחיר what is the charge? how much (is it)?  ב״מ פ״ד מ״י: לא יאמר בכמה חפץ זה והוא אינו רוצה ליקח.</p>","notation":[]},"39765":{"h":"כְּכַמָּה בְחֹדֶשׁ","r":"KRU09511","alt":[],"source":"krupnik","glosses":[{"text":"what day of the month?","label":""}],"html":"<p>באיזה יום מימי החודש what day of the month?  סנה׳ פ״ה מ״א: היו בודקין אותן בשבע חקירות באיזה שבוע באיזו שנה באיזה חדש בכמה בחדש וכו׳.</p>","notation":[]},"39766":{"h":"כְּמֵהוֹת","r":"KRU09512","alt":["כְּמֵהִים","כְּמֵהִין"],"source":"krupnik","glosses":[{"text":"mushrooms","label":""}],"html":"<p>ונ״ר, הצמחים הרכים והחלולים שבקרקע רטוב, פטריות mushrooms  ב״ר פס״ט: ככמהות הללו שהן מצפין למים; ירוש׳ תענ׳ פ״ג ס״ז ע״א: ונתנגבה הארץ ויצאו ומצאו מדבר מלא כמהים; מעש׳ פ״א מ״ח ע״ד: כמהין ופטריות שאינן נזרעות ומצמיחות.</p>","notation":[]},"39767":{"h":"כַּמּוֹנָא","r":"KRU09514","alt":[],"source":"krupnik","glosses":[{"text":"cumin","label":""}],"html":"<p>כמון, מין זרעון חריף cumin  שבת ק״י ע״ב: בונא דכמונא בונא דמריקא וכו׳.</p>","notation":["ז׳"]},"39768":{"h":"כָּמוֹנָא","r":"KRU09515","alt":[],"source":"krupnik","glosses":[{"text":"insidiousness","label":""}],"html":"<p>ערמה insidiousness  תרג׳ ירוש׳ שמ׳ כ״א י״ד (בערמה): בכמונא.</p>","notation":["ז׳"]},"39769":{"h":"כָּמוּשׁ","r":"KRU09516","alt":[],"source":"krupnik","glosses":[{"text":"withered","label":""}],"html":"<p>קמוט ויבש, בלה withered  שהש״ר ב׳ ב׳: שושנה זו שרב יוצא עליה והיא כמושה יצא טל היא מפרחת.</p>","notation":["ת׳"]},"39770":{"h":"כְּמוֹת","r":"KRU09517","alt":[],"source":"krupnik","glosses":[{"text":"like, as","label":""}],"html":"<p>כמו like, as  תוס׳ מע״ש ג׳ א׳: פודין מעשר שני בשעת הזול כמות שחנוני לוקח ולא כמות שמוכר.</p>","notation":["מה״ח"]},"39771":{"h":"כְּמִי","r":"KRU09518","alt":[],"source":"krupnik","glosses":[{"text":"as if, like","label":""}],"html":"<p>כאילו, כמו as if, like  ירוש׳ סוכה פ״ג נ״ג ע״ג: נחלק המתאים כמי שנפרדו העלים.</p>","notation":[]},"39772":{"h":"כְּלִי","r":"KRU09519","alt":[],"source":"krupnik","glosses":[{"text":"a vessel direct from the fire","label":""}],"html":"<p>כְּלִי רִאשׁוֹן a vessel direct from the fire  חול׳ ק״ד ע״ב: כלי ראשון.</p>","notation":[]},"39773":{"h":"כְּלִי שֵׁנִי","r":"KRU09520","alt":[],"source":"krupnik","glosses":[{"text":"a vessel into which a boiling mass has been poured","label":""}],"html":"<p>שניצוקו לתוכו חמים מכלי ראשון a vessel into which a boiling mass has been poured  שבת מ׳ ע״ב: כלי שני.</p>","notation":[]},"39774":{"h":"כמיך","r":"KRU09521","alt":[],"source":"krupnik","glosses":[{"text":"a word in a charm formula","label":""}],"html":"<p>אחת התיבות בנוסח של לחש a word in a charm formula  שבת ס״ז ע״א: כמון כמיך.</p>","notation":[]},"39775":{"h":"כָּמַךְ","r":"KRU09523","alt":["כָּמְכָא"],"source":"krupnik","glosses":[{"text":"a milk sauce","label":""}],"html":"<p>מין טיבול־חלב a milk sauce  נדה נ״א ע״ב: שבת העשויה לכמך; חול׳ קי״ב ע״א: כדא דמלחא גבי כדא דכמכא.</p>","notation":[]},"39776":{"h":"כַּתְלָנִית","r":"KRU09524","alt":[],"source":"krupnik","glosses":[{"text":"chamaeleon","label":""}],"html":"<p>מין חיה ססגונית chamaeleon  מדר׳ תה׳ ע״ח י״א: מין חיה וכו׳ ושמה כתלנית.</p>","notation":["נ׳"]},"39777":{"h":"כִּמֵּן","r":"KRU09526","alt":[],"source":"krupnik","glosses":[{"text":"to hide","label":"פיעל,"},{"text":"to keep witnesses hidden","label":"הִכְמִין הפ׳,"}],"html":"<p>פיעל, טמן to hide  מעש׳ פ״ד מ״א: המכמן באדמה פטור.\nהִכְמִין הפ׳, שם עדים במארב to keep witnesses hidden  ירוש׳ יבמ׳ פט״ז ט״ו ע״ד: מכמינים עליו ב׳ עדים וכו׳ כדי שיהו רואין אותו ושומעין את קולו.</p>","notation":[]},"39778":{"h":"כְּמַן","r":"KRU09527","alt":[],"source":"krupnik","glosses":[{"text":"to lie in wait","label":""},{"text":"to hide","label":""}],"html":"<p>ארב to lie in wait  תרג׳ שמ׳ כ״א י״ג (ואשר לא צדה): ודלא כמן ליה. אַכְמֵן  אפ׳, 1) כנ״ל. תרג׳ איכה ג׳ י׳ (דוב אורב): דובא מכמן. 2) צפן to hide  תרג׳ מש׳ י׳ י״ב (מכסה שנאה): מכמין בעיל דבבא. 3) עי׳ הִכְמִין. סנה׳ כ״ט ע״ב: ההוא דאכמין ליה עדים לחבריה וכו׳. אִתְכְּמַן אתפ׳, עי׳ כְּמַן. תרג׳ הוש׳ ז׳ ו׳ (בארבם): באתכמוניהון. </p>","notation":["פ״י"]},"39779":{"h":"כְּמָּן","r":"KRU09528","alt":[],"source":"krupnik","glosses":[{"text":"how many?","label":""}],"html":"<p>כמה how many?  ? ירוש׳ ע״ז פ״ב מ״א ע״א: כמן קטל.</p>","notation":["מה״ש"]},"39780":{"h":"כְּמָנָא","r":"KRU09529","alt":[],"source":"krupnik","glosses":[{"text":"ambush","label":"1"},{"text":"insidiousness","label":"2"}],"html":"<p>1 מארב ambush  תרג׳ שופ׳ ט׳ ל״ה (מן המארב): מן כמנא.\n2 ערמה insidiousness  תרג׳ יר׳ ט׳ ז׳ (ובקרבו ישים ארבו): ובמעוהי משוי כמנתיה.</p>","notation":["נ׳"]},"39781":{"h":"כַּמָּס","r":"KRU09531","alt":[],"source":"krupnik","glosses":[{"text":"gag","label":""}],"html":"<p>מחסום gag  פסיק׳ שובה קנ״ט ע״ב: ואחר כך הוא מכה אותם וכו׳ ואחר כך הוא נותן להם כמס.</p>","notation":["ז׳"]},"39782":{"h":"כְּמֵסַת","r":"KRU09532","alt":[],"source":"krupnik","glosses":[{"text":"worthy, able, adequate","label":""}],"html":"<p>ראוי, מוכשר worthy, able, adequate  תרג׳ ירוש׳ ויק׳ כ״ג כ״ט: נפש דכמסת למצום ולא ציימא.</p>","notation":["ת׳"]},"39783":{"h":"כָּמר","r":"KRU09533","alt":[],"source":"krupnik","glosses":[{"text":"to store fruits in the ground","label":""},{"text":"to lay a net","label":""}],"html":"<p>1) שם פירות באדמה to store fruits in the ground  ב״מ פ״ט ע״ב: ולא יכמור באדמה. 2) פרס מכמורת to lay a net  ירוש׳ יבמ׳ פט״ז ט״ו ע״ד: מעשה בשנים שירדו לכמור מכמורת לירדן. כִּמֵּר פיעל כנ״ל 2. תוס׳ יבמ׳ י״ד ו׳: מעשה בשנים שהיו מכמרין מכמרות בירדן. </p>","notation":["פ״י"]},"39784":{"h":"כְּמַר","r":"KRU09534","alt":[],"source":"krupnik","glosses":[{"text":"to keep warm","label":""}],"html":"<p>חימם, to keep warm  ב״מ ע״ד ע״א: מחוסר מכמר ועיולי.</p>","notation":["פ״י"]},"39785":{"h":"כְּמַר רַחֲמִין","r":"KRU09535","alt":[],"source":"krupnik","glosses":[{"text":"to feel compassion","label":""}],"html":"<p>ריחם to feel compassion  תרג׳ יב״ע דב׳ י״ג י״ח: ויכמור עליכון רחמין.</p>","notation":[]},"39786":{"h":"כְּמָרָא","r":"KRU09536","alt":[],"source":"krupnik","glosses":[{"text":"overripe fruits","label":""}],"html":"<p>פירות בשלים ביותר overripe fruits  בר׳ מ׳ ע״ב: בושלי כמרא.</p>","notation":["נ׳"]},"39787":{"h":"כַּמְרוֹסָא","r":"KRU09537","alt":[],"source":"krupnik","glosses":[{"text":"vault","label":""}],"html":"<p>כיפה vault  במ״ר פי״ב: כמין כמרוסא היו כיפין עשויות.</p>","notation":["נ׳"]},"39788":{"h":"כָּמַשׁ","r":"KRU09539","alt":[],"source":"krupnik","glosses":[{"text":"to wither","label":""}],"html":"<p>נִכְמַשׁ נפ׳, נבל, נעשה יבש ובלה to wither  ירוש׳ מעש״ש פ״ד נ״ד ע״ד: מניחן עליו עד שיכמושו; שהש״ר ב׳ א׳: ולא כשושנת ההר שנוחה להכמש אלא כשושנת העמקים שמרטבת והולכת.</p>","notation":["פ״ע,"]},"39789":{"h":"כְּמָת־","r":"KRU09544","alt":[],"source":"krupnik","glosses":[{"text":"like","label":""}],"html":"<p>כמו like  תרג׳ איוב כ״ח ה׳ (כמו אש): דכמת אשתא.</p>","notation":[]},"39790":{"h":"כַּנָּא","r":"KRU09546","alt":[],"source":"krupnik","glosses":[{"text":"the stem of a plant","label":"1"},{"text":"a dry measure","label":"2"}],"html":"<p>1 חיבור לקרקע the stem of a plant  בר׳ נ״ז ע״ב: ראשי לפתות כי חזא בכנייהו חזא.\n2 מין מדת היבש a dry measure  כת׳ צ״ט ע״ב: באתרא דכיילי בכני וכו׳ כנא כנא בפרוטה.</p>","notation":["ז׳"]},"39791":{"h":"כַּנְדָּא","r":"KRU09547","alt":[],"source":"krupnik","glosses":[{"text":"earthen ware","label":"1"},{"text":"blain","label":"2"},{"text":"a gown","label":"3"}],"html":"<p>1 כלי חרס earthen ware  פס׳ ל׳ ע״א: אשוו זביני אכנדייכו.\n2 אבעבועה blain  חול׳ מ״ח ע״ב: דקיימי כנדי כנדי.\n3 מין מלבוש a gown  מו״ק כ״ד ע״א (לגי׳ הערוך): תליסר כנדי מאני.</p>","notation":["ז׳"]},"39792":{"h":"כַּנְדּוֹקָא","r":"KRU09548","alt":[],"source":"krupnik","glosses":[{"text":"dealer in pottery","label":""}],"html":"<p>מוכר כלי חרס dealer in pottery  חול׳ מ״ט ע״ב: מניומין כנדוקא.</p>","notation":["ז׳"]},"39793":{"h":"כִּנָּה","r":"KRU09549","alt":[],"source":"krupnik","glosses":[{"text":"to circumscribe","label":""}],"html":"<p>פיעל, דיבר בלשון נקיה to circumscribe  תוס׳ מגי׳ ד׳ ל״ט: כל המקראות הכתובין לגנאי מכנין אותן לשבח.</p>","notation":["Marked biblical in source"]},"39794":{"h":"כַּנָּה","r":"KRU09550","alt":[],"source":"krupnik","glosses":[{"text":"base, stand","label":"1"},{"text":"ruler","label":"2"}],"html":"<p>1 בסיס base, stand  בל׳ פ״ז מ״ו: מן הכנה ולחוץ טהור מן הכנה ולפנים ומקום הכנה טמא.\n2 סרגל לשרטוט ruler  שם פי״ב מ״ח: האולר והקולמוס וכו׳ והכנה.</p>","notation":["Marked biblical in source"]},"39795":{"h":"כִּנוּי","r":"KRU09552","alt":[],"source":"krupnik","glosses":[{"text":"byname, surname","label":"1"},{"text":"a substitute for the Divine Name","label":"2"}],"html":"<p>1 שם לואי byname, surname  שבוע׳ פ״ז מ״ח: והמקלל אביו ואמו אינו חייב עד שיקללם בשם קללם בכנוי ר׳ מאיר מחייב וחכמים פוטרים.\n2 תואר לאלהים a substitute for the Divine Name  שם פ״ד מי״ג: משביע אני עליכם וכו׳ בחנון ורחום בארך אפים ברב חסד ובכל הכנויין.</p>","notation":["ז׳"]},"39796":{"h":"כָּנוֹנָא","r":"KRU09554","alt":[],"source":"krupnik","glosses":[{"text":"brazier","label":""}],"html":"<p>מחתת גחלים brazier  ביצה כ״א ע״ב: מי לא אמר רבא מטלטלין כנונא אגב קטמיה.</p>","notation":["ז׳"]},"39797":{"h":"כָּנוֹנֵי","r":"KRU09555","alt":[],"source":"krupnik","glosses":[{"text":"a Babylonian festive time","label":""}],"html":"<p>חג בבלי a Babylonian festive time  ירוש׳ ע״ז פ״א ל״ט ע״ג: מחורי וכנוני.</p>","notation":["ז״ר"]},"39798":{"h":"כִּנּוּס","r":"KRU09556","alt":[],"source":"krupnik","glosses":[{"text":"gathering","label":"1"},{"text":"piling up","label":"2"}],"html":"<p>1 קבוץ ואסיפה gathering  סנה׳ פ״ח מ״ה: כנוס לרשעים רע להם ורע לעולם.\n2 קליטה piling up  כל׳ פט״ו מ״ט: העשוי לקבלה טמא לכנוס טהור. ועי׳ כִּינוּס.</p>","notation":["ז׳"]},"39799":{"h":"כְּנוּפְיָא","r":"KRU09557","alt":[],"source":"krupnik","glosses":[{"text":"assembly","label":""}],"html":"<p>קבוץ assembly  גיט׳ י״א ע״א: רבינא סבר לאכשורי בכנופיאתה דארמאי.</p>","notation":["ז׳"]},"39800":{"h":"כְּנוֹשָׁאָה","r":"KRU09558","alt":[],"source":"krupnik","glosses":[{"text":"sweeper","label":""}],"html":"<p>מי שמטאטא sweeper  חול׳ ס׳ ע״א: כנושאי זלוחאי.</p>","notation":["ז׳"]},"39801":{"h":"כַּנֵּי","r":"KRU09559","alt":[],"source":"krupnik","glosses":[{"text":"to be surnamed","label":""},{"text":"to associate one’s self","label":""}],"html":"<p>עי׳ כִּנָּה. שבוע׳ ל״ו ע״א: הני מילי מתניתין אבל בקראי אימא לא מכנינן קא משמע לן. אִתְכְּנִי אתפ׳, 1) נקרא, נתכנה to be surnamed  תרג׳ יש׳ א׳ ד׳: אתכניאו בזרעא רחימא. 2) התחבר to associate one’s self  תרג׳ יח׳ כ״ט ז׳ (בתפשם): באתכניותהון. </p>","notation":["פַעל"]},"39802":{"h":"כְּנִימָא","r":"KRU09560","alt":[],"source":"krupnik","glosses":[{"text":"vermin","label":""}],"html":"<p>תולעים vermin  ספרי דב׳ מ׳: כנימה ורקבובית בפירות.</p>","notation":["נ׳"]},"39803":{"h":"כְּנִיסָה","r":"KRU09561","alt":[],"source":"krupnik","glosses":[{"text":"assembly","label":"1"},{"text":"entering","label":"2"}],"html":"<p>1 אספה assembly  מגי׳ פ״א מ״א: שהכפרים מקדימין ליום הכניסה.\n2 ביאה פנימה entering  כר׳ פ״ט מ״א: אחת בכניסתו ואחת ביציאתו.</p>","notation":["נ׳"]},"39804":{"h":"כְּנִיסְתָּא","r":"KRU09562","alt":[],"source":"krupnik","glosses":[{"text":"school","label":""}],"html":"<p>בית הספר school  ירוש׳ הור׳ פ״ב מ״ו ע״ד: מילה דמיינוקאה אמרין בכניסתא בכל יום את שאיל לי.</p>","notation":["נ׳"]},"39805":{"h":"כְּנִיעַ","r":"KRU09563","alt":[],"source":"krupnik","glosses":[{"text":"depressed","label":""}],"html":"<p>מדוכא, בעל רוח נואש depressed  ירוש׳ תר׳ פי״א מ״ח ע״ב: ע״י דאינון כניעין וכו׳.</p>","notation":["ת׳"]},"39806":{"h":"כְּנִישׁ","r":"KRU09564","alt":[],"source":"krupnik","glosses":[{"text":"festive gathering","label":""}],"html":"<p>אספת חג festive gathering  תרג׳ דב׳ ט״ז ח׳ (וביום השביעי עצרת): וביומא שביעאה כניש.</p>","notation":["ז׳"]},"39807":{"h":"כְּנִישָׁא","r":"KRU09565","alt":["כְּנִישְׁתָּא"],"source":"krupnik","glosses":[{"text":"gathering; assembly","label":"1"},{"text":"synagogue","label":"2"},{"text":"broom","label":"3"}],"html":"<p>1 אספה, קהל gathering; assembly  תרג׳ יואל א׳ י״ד (קראו עצרה): ערעו כנישא; תרג׳ ירוש׳ בר׳ מ״ט ז׳: כנישתא דיעקב.\n2 בית הכנסת synagogue  ירוש׳ מו״ק פ״ג פ״א ע״ד: עברה קומי חדא כנישא; מגי׳ כ״ט ע״א: אבוה דשמואל ולוי הוו יתבי בכנישתא.\n3 מטאטא broom  שבי׳ כ״ב ל״ג ע״ד: דכנישתא חדתא וחרוותה.</p>","notation":[]},"39808":{"h":"כִּנֵּן","r":"KRU09571","alt":[],"source":"krupnik","glosses":[{"text":"to wind around","label":"פיעל,"}],"html":"<p>פיעל, כרך מסביב to wind around  פרה פ״ז מ״ז: המכנן את החבל על יד על יד וכו׳.</p>","notation":[]},"39809":{"h":"כְּנָנִית","r":"KRU09572","alt":[],"source":"krupnik","glosses":[{"text":"sinnous line","label":""}],"html":"<p>עגול ועקמומית sinnous line  חול׳ נ״ו ע״ב: שברא הקב״ה כנניות באדם שאם נהפך אחת מהן אינו יכול לחיות.</p>","notation":["נ׳"]},"39810":{"h":"כָּנַס","r":"KRU09573","alt":[],"source":"krupnik","glosses":[{"text":"to bring in, to shelter","label":""},{"text":"to take, to accept","label":""},{"text":"to take a woman home","label":""},{"text":"to form a recess in a wall","label":""},{"text":"to absorb","label":""},{"text":"to grow smaller","label":""},{"text":"to enter","label":""},{"text":"to be married","label":""},{"text":"to bring in","label":""},{"text":"to yield","label":""},{"text":"to assemble","label":""}],"html":"<p>1) הביא והכניס פנימה to bring in, to shelter  ב״ק פ״ו מ״א: הכונס צאן לדיר ונעל בסניה כראוי ויצאה והזיקה. 2) לקח, קיבל to take, to accept  גיט׳ פ״א מ״ב: כנסי שטר חוב זה. 3) נשא אשה ולקחה לביתו to take a woman home  יבמ׳ פ״ב מ״ח: הנטען על אשת איש והוציאוה מתחת ידו אעפ״י שכנס יוציא. 4) עשה משקע רחב בבנין to form a recess in a wall  ב״ב פ״א מ״ח: אין מוציאין זיזין וגזוזטראות לרשות הרבים אלא אם רצה כונס לתוך שלו ומוציא. 5) קלט, ינק to absorb  כל׳ פ״י מ״ח: בכונס משקה. 6) נתמעט to grow smaller  נגע׳ פ״ד מ״ז: כנסה ופשתה פשתה וכנסה וכו׳. נִכְנַס נפ׳, 1) בא פנימה to enter  אבות פ״ד מט״ו: התקן עצמך בפרוזדור כדי שתכנס לטרקלין. 2) נישאה האשה to be married  ירוש׳ יבמ׳ מ״ד ו׳ ע״ב: היכנסי וגדלי את בני אחותך. הִכְנִיס הפ׳, 1) הביא פנימה to bring in  פסח׳ פ״א מ״א: כל מקום שאין מכניסין בו חמץ אין צריך בדיקה. 2) הביא פרי to yield  שבי׳ פ״ד מ״ט: זתים משיכניסו רביעית לסאה וכו׳. הִתְכַּנֵס התפ׳, 1) התאסף והתקבץ to assemble  ירוש׳ סנה׳ פ״ז כ״ה ע״ד: אם מתכנסין הן כל באי העולם אינן יכולין לבראות יתוש אחד ולזרוק בו נשמה. 2) עי׳ נִכְנַס 1. ב״ר פי״ב: מתכנסין ויוצאין. </p>","notation":["Marked biblical in source"]},"39811":{"h":"כְּנַס","r":"KRU09574","alt":[],"source":"krupnik","glosses":[{"text":"to gather","label":"1"},{"text":"to marry","label":"2"},{"text":"to enter","label":"3"}],"html":"<p>1 קיבץ to gather  תרג׳ יב״ע בר׳ י״ח ג׳: עד דאיכנוס עיבורייא תחות אילנא.\n2 נשא אשה to marry  ירוש׳ כת׳ פ״א כ״ד ע״ד: אילין דכנסין ארמלן צריך לכונסה מבעוד יום.\n3 נכנס to enter  ירוש׳ סנה׳ פ״ו כ״ג ע״ג: כיון דכנס הדא וכו׳.</p>","notation":["פ״י"]},"39812":{"h":"כְּנֵסִיָּה","r":"KRU09575","alt":["כְּנֶסֶת"],"source":"krupnik","glosses":[{"text":"assembly, union","label":"1"},{"text":"synagogue","label":"2"}],"html":"<p>1 אספה, קיבוץ assembly, union  אבות פ״ד מי״א: כל כנסיה שהיא לשם שמים סופה להתקיים; שם פ״א מ״א: ונביאים מסרוה לאנשי כנסת הגדולה.\n2 בית הכנסת, בית התפלה synagogue  במ״ר פ״א: זו העיר טובה לי מכל המדינות בו אני בונה כנסיה ודר בתוכו; יומא פ״ז מ״א; חזן הכנסת נוטל ספר תורה ונותנו לראש הכנסת וכו׳.</p>","notation":[]},"39813":{"h":"כְּנֶסֶת הַגְּדוֹלָה","r":"KRU09576","alt":[],"source":"krupnik","glosses":[{"text":"the Great Assembly established under Ezra and Nehemiah","label":""}],"html":"<p>סנהדרין שנתיסדה בימי עזרא ונחמיה the Great Assembly established under Ezra and Nehemiah  אבות פ״א מ״ב: שמעון הצדיק היה משירי כנסת הגדולה.</p>","notation":[]},"39814":{"h":"כְּנֶסֶת יִשְׂרָאֵל","r":"KRU09577","alt":[],"source":"krupnik","glosses":[{"text":"the congregation of Israel","label":""}],"html":"<p>כלל האומה הישראלית the congregation of Israel  פס׳ קי״ח ע״ב: אמרה כנסת ישראל לפני הקב״ה וכו׳.</p>","notation":[]},"39815":{"h":"כנע","r":"KRU09578","alt":[],"source":"krupnik","glosses":[{"text":"to lower one's self","label":"אִיכְּנַע, אִתְכַּנַּע אתפ׳, 1"},{"text":"to bow","label":"אִיכְּנַע, אִתְכַּנַּע אתפ׳, 2"}],"html":"<p>אִיכְּנַע, אִתְכַּנַּע אתפ׳, 1 נכנע, היה כפוף to lower one&#x27;s self  ירוש׳ תענ׳ פ״ג ס״ו ע״ג: דרומאי ליבהון רכיך ושמעין מילא דאורייתא ומתכנעין.\nאִיכְּנַע, אִתְכַּנַּע אתפ׳, 2 החוה קידה to bow  מו״ק ט״ז ע״ב: הוה חלף ואזיל צורבא מרבנן ולא איכנעא מקמיה.</p>","notation":["Source marks no qal form"]},"39816":{"h":"כְּנַעֲנָאָה","r":"KRU09580","alt":[],"source":"krupnik","glosses":[{"text":"Canaanite","label":""}],"html":"<p>כנעני Canaanite  תרג׳ יב״ע בר׳ י״ב ו׳ (והכנעני): כנענאי.</p>","notation":["ז׳"]},"39817":{"h":"כְּנַף","r":"KRU09581","alt":[],"source":"krupnik","glosses":[{"text":"gather","label":""}],"html":"<p>קיבץ gather  שבת ע״ג ע״ב: האי מאן דכניף מילחא ממלחתא וכו׳.</p>","notation":["פ״י"]},"39818":{"h":"כַּנֵּף","r":"KRU09582","alt":[],"source":"krupnik","glosses":[{"text":"to fold, to crease","label":"פַעל, 2"},{"text":"to be assembled, to meet","label":"אִתְכְּנִיף, אִיכְּנִיף אתפ׳,"}],"html":"<p>פַעל, 1 כנ״ל. בר׳ נ״ח ע״ב: דמכנפי.\nפַעל, 2 קיפל to fold, to crease  שבת קמ״ז ע״א: כל אדעתא דלכנופי אסור.\nאִתְכְּנִיף, אִיכְּנִיף אתפ׳, נתכנס to be assembled, to meet  שהש״ר ח׳ ז׳: ואי מתכנפין כל מלכי ארעא; סנה׳ ס״ז ע״ב: האי מיכניף ליה והאי לא מיכניף ליה.</p>","notation":[]},"39819":{"h":"כָּנָף","r":"KRU09583","alt":[],"source":"krupnik","glosses":[{"text":"lap of the lungs","label":"1"},{"text":"fore-leg","label":"2"},{"text":"hand","label":"3"},{"text":"key (of a musical instrument)","label":"4"}],"html":"<p>1 אונא של הריאה lap of the lungs  ויק״ר פי״ח: כנפי הריאה שמשם יוצא הקול.\n2 הרגל הקדמית של בעל חי fore-leg  פס׳ פ״ז מי״א: כל הנאכל בשור הגדול יאכל בגדי הרך וראשי הכנפים וכו׳.\n3 יד hand  תוס׳ דמ׳ פ״ב מי״א: קיבל עליו לטהרות ולא קיבל עליו לכנפים וכו׳.\n4 מנענע של כלי זמר key (of a musical instrument)  כל׳ פי״א מ״ו: סימפוניה אם יש בה בית קיבול כנפים וכו׳.</p>","notation":["Marked biblical in source"]},"39820":{"h":"כנש","r":"KRU09584","alt":[],"source":"krupnik","glosses":[{"text":"to assemble, to join","label":"הִתְכַּנֵּשׁ התפ׳,"}],"html":"<p>הִתְכַּנֵּשׁ התפ׳, התקבץ והתכנס to assemble, to join  שהש״ר א׳ ג׳: והלא אם מתכנשין כל העולם לבראות יתוש אחד אינן יכולין לבראותו.</p>","notation":["Source marks no qal form"]},"39821":{"h":"כְּנַשׁ","r":"KRU09585","alt":[],"source":"krupnik","glosses":[{"text":"to gather in","label":"1"},{"text":"i>to sweep","label":"2"}],"html":"<p>1 קיבץ to gather in  ירוש׳ מעש״ש פ״ד נ״ה ע״ג: מה דאת זרע לית את כנש.\n2 טאטא &lt;i&gt;to sweep  ב״מ פ״ה ע״א: יומא חד הוה קא כנשא אמתא דבי רבי ביתא.</p>","notation":["פ״י"]},"39822":{"h":"כַּנֵּשׁ","r":"KRU09586","alt":[],"source":"krupnik","glosses":[{"text":"to be gathered, to meet","label":""}],"html":"<p>כנ״ל 1. ירוש׳ בר׳ פ״ט י״ד ע״ד: בשעה דמכנשין בדר ובשעה דמבדרין כניש. אִתְכְּנַשׁ אתפ׳, נתקבץ ונתלקט to be gathered, to meet  קהל״ר ט׳ י׳: אתכנשון כל קרייתא. </p>","notation":["פַעל"]},"39823":{"h":"כִּנְשָׁא","r":"KRU09587","alt":[],"source":"krupnik","glosses":[{"text":"people","label":""}],"html":"<p>עם people  תרג׳ בר׳ י״ז ט״ז (לגויים): לכנשן.</p>","notation":["ז׳"]},"39824":{"h":"כְּנָת","r":"KRU09588","alt":["כַּנְתָא"],"source":"krupnik","glosses":[{"text":"ileum","label":""}],"html":"<p>המֵעה המעוקם ileum  ילק׳ קהל׳ תתקע״ו: ומקיבתא לאסטומכא וכו׳ ומכרוכא עבה לכנת מעיא; חול׳ מ״ח ע״ב: הדורא דכנתא.</p>","notation":[]},"39825":{"h":"כַּנְתִּי","r":"KRU09589","alt":[],"source":"krupnik","glosses":[{"text":"a word in a charm formula","label":""}],"html":"<p>תיבה בנוסח של לחש a word in a charm formula  יומא פ״ד ע״א: כנתי כנתי קלירוס.</p>","notation":[]},"39826":{"h":"כָּס","r":"KRU09591","alt":[],"source":"krupnik","glosses":[{"text":"cup","label":""}],"html":"<p>כוס cup  תרג׳ יר׳ א׳ ה׳: כס דלוט.</p>","notation":["ז׳"]},"39827":{"h":"כַּסָּא","r":"KRU09594","alt":[],"source":"krupnik","glosses":[{"text":"cup","label":"1"},{"text":"a pie","label":"2"}],"html":"<p>1 כוס cup  בר׳ ל״א ע״א: כסא דזוגיתא חיורתא.\n2 מאכל a pie  ביצה ט״ז ע״א: כסא דהרסנא.</p>","notation":["ז׳"]},"39828":{"h":"כִּסֵּא","r":"KRU09595","alt":[],"source":"krupnik","glosses":[{"text":"the throne of Divine Majesty","label":""}],"html":"<p>כִּסֵא הַכָּבוֹד מושב השכינה כביכול the throne of Divine Majesty  יומא פ״ו ע״א: גדולה תשובה שמגעת עד כסא הכבוד.</p>","notation":["Marked biblical in source"]},"39829":{"h":"כְּסָאן","r":"KRU09596","alt":[],"source":"krupnik","glosses":[{"text":"loam","label":""}],"html":"<p>טיט loam  תרג׳ איוב מ״א כ״ב (עלי טיט): עלוי כסאן.</p>","notation":["ז׳"]},"39830":{"h":"כְּסָאנֵי","r":"KRU09597","alt":[],"source":"krupnik","glosses":[{"text":"roasted ears","label":""}],"html":"<p>שבלים קלויות roasted ears  עירי כ״ט ע״ב: הני כסאני מעלו לליבא וכו׳.</p>","notation":["ז״ר"]},"39831":{"h":"כַּסְדָּאָה","r":"KRU09599","alt":[],"source":"krupnik","glosses":[{"text":"Chaldean","label":""}],"html":"<p>כשדי Chaldean  תרג׳ בר׳ י״א כ״ח (באור כשדים): באורא דכסדאי.</p>","notation":["ז׳"]},"39832":{"h":"כְּסוּ","r":"KRU09600","alt":[],"source":"krupnik","glosses":[{"text":"clothing","label":""}],"html":"<p>כסות, מלבוש clothing  תרג׳ שמ׳ כ״ב ח׳ (על שה על שלמה): על איטר על כסו.</p>","notation":["נ׳"]},"39833":{"h":"כִּסּוּי","r":"KRU09601","alt":[],"source":"krupnik","glosses":[{"text":"covering","label":"1"},{"text":"cover","label":"2"}],"html":"<p>1 פעולת המכסה covering  חול׳ פ״ד ע״א: שאינו מחוסר אלא שפיכה וכסוי.\n2 מכסה cover  שבת פי״ז מ״ח: כל כסויי כלים שיש להם בית אחיזה וכו׳.</p>","notation":["ז׳"]},"39834":{"h":"כָּסוּל","r":"KRU09602","alt":[],"source":"krupnik","glosses":[{"text":"with a deformed hip","label":""}],"html":"<p>שאחת מירכותיו גבוהה with a deformed hip  בכורות פ״ו מ״ז: וכסול שאחת מירכותיו גבוהה.</p>","notation":["ת׳"]},"39835":{"h":"כסוסטא","r":"KRU09603","alt":["כסוסטי"],"source":"krupnik","glosses":[{"text":"a dry and liquid measure","label":""}],"html":"<p>מין מדת הלח והיבש a dry and liquid measure  ב״ר פ״ד: המים העליונים יתירין על התחתונים כשלשים כסוסטאות (ילק׳ בר׳ ה׳: כסוסטיאות).</p>","notation":[]},"39836":{"h":"כָּסוּף","r":"KRU09604","alt":[],"source":"krupnik","glosses":[{"text":"bright","label":""}],"html":"<p>מזהיר bright  ילק׳ במ׳ צ״ב: וותיקים וכו׳ כסופים.</p>","notation":["ת׳"]},"39837":{"h":"כָּסַח","r":"KRU09606","alt":[],"source":"krupnik","glosses":[{"text":"to cut down, to trim","label":"כִּסַּח פיעל"},{"text":"to be cut down","label":"נִכְסַח נפ׳,"}],"html":"<p>כִּסַּח פיעל קטע וקצר to cut down, to trim  כלא׳ פ״ב מ״ד: אם נכש או כיסח אומרים לו עקור את הכל חוץ ממין אחד.\nנִכְסַח נפ׳, נקצר ונגזז to be cut down  מדרש תה׳ פ׳ ז׳: וכל דבר שנכסח מחליף.</p>","notation":["Marked biblical in source"]},"39838":{"h":"כַּסֵּי","r":"KRU09608","alt":[],"source":"krupnik","glosses":[{"text":"to cover, to hide, to conceal","label":"פַעל,"},{"text":"to be covered, to be hidden","label":"אִיתְכַּסִי, אִיכַּסִי אתפ׳,"}],"html":"<p>פַעל, כיסה to cover, to hide, to conceal  תרג׳ בר׳ ל״ח ט״ו (כסתה פניה): כסיאת אפהא; שם מ״ז י״ח (לא נכחד מאדוני): לא נכסי מן רבוני.\nאִיתְכַּסִי, אִיכַּסִי אתפ׳, נתכסה, נסתתר to be covered, to be hidden  קיד׳ ל״ג ע״א: חלף ההוא גברא ולא מיכסי רישא אמר כמה חציף האי גברא; תרג׳ דב׳ כ״ב ג׳ (לא תוכל להתעלם): לית לך רשו לאתכסאה.</p>","notation":[]},"39839":{"h":"כסידא","r":"KRU09610","alt":[],"source":"krupnik","glosses":[{"text":"half ripe","label":""}],"html":"<p>בוסר half ripe  תרג׳ יב״ע שמ׳ ט׳ ל״א (והשעורה אביב): שערייא הוו כסידן.</p>","notation":["ת׳","Source emendation: בְּסִירָא"]},"39840":{"h":"כְּסִיָּיה","r":"KRU09611","alt":["כְּסִיַּית עֵינַיִם"],"source":"krupnik","glosses":[{"text":"blindness","label":""}],"html":"<p>סנורים blindness  מגי׳ כ״ח ע״א: אל תקרי כסות אלא כסיית עינים.</p>","notation":[]},"39841":{"h":"כְּסִיתָא","r":"KRU09613","alt":[],"source":"krupnik","glosses":[{"text":"coral","label":""}],"html":"<p>אלמוג coral  ר״ה כ״ג ע״א: אלמוג – כסיתא.</p>","notation":["נ׳"]},"39842":{"h":"כִּסְכּוּס","r":"KRU09614","alt":[],"source":"krupnik","glosses":[{"text":"rubbing","label":""}],"html":"<p>שפשוף rubbing  זבח׳ צ״ד ע״ב: כל כיבוס דלית ליה כסכוס לא שמיה כבוס.</p>","notation":["ז׳"]},"39843":{"h":"כִּסְכֵּס","r":"KRU09615","alt":[],"source":"krupnik","glosses":[{"text":"to rub, to scour","label":"1"},{"text":"to chew","label":"2"}],"html":"<p>1 שפשף ומלל to rub, to scour  נדה פ״ט מ״ז: וצריך לכסכס שלש פעמים לכל אחד ואחד.\n2 כסס ולעס to chew  תנח׳ ויגש ח׳: שהיה נוטל אפונין של ברזל ונותנן לתוך פיו ומכסכס בהן. ועי׳ כָּסַַס.</p>","notation":["פ״י"]},"39844":{"h":"כַּסְכַּס","r":"KRU09616","alt":[],"source":"krupnik","glosses":[{"text":"leather thong","label":""}],"html":"<p>רצועה leather thong  שבת קל״ט ע״ב: בכילה ובכסכסיה.</p>","notation":["ז׳"]},"39845":{"h":"כִּסְלָא","r":"KRU09617","alt":[],"source":"krupnik","glosses":[{"text":"ridge","label":"1"},{"text":"loin","label":"2"},{"text":"Orion","label":"3"}],"html":"<p>1 תלם ridge  בר׳ ו׳ ע״א: וקיימו עלן כי כסלא לאוגיא.\n2 כסלים, מתנים loin  תרג׳ תה׳ ל״ח ח׳ (כסלי): כסלי.\n3 מערכת הכוכבים „כסיל“ Orion  בר׳ נ״ח ע״ב: ואי עבר כסלא חרב עלמא.</p>","notation":["ז׳"]},"39846":{"h":"כְּסַן","r":"KRU09618","alt":[],"source":"krupnik","glosses":[{"text":"to chastise","label":"כַּסֵּן פַעל, אַכְסֵן אפ׳,"}],"html":"<p>כַּסֵּן פַעל, אַכְסֵן אפ׳, ענש to chastise  תרג׳ יב״ע דב׳ כ״א י״ח (ויסרו אותו): ויכסנון יתיה; תה׳ ל״ח ב׳ (אל בקצפך תוכיחני): לא ברוגזך תכסן יתי: איוב ט׳ ל״ג (לא יש בינינו מוכיח): לא אית ביננא מכסין.</p>","notation":["פ״י"]},"39847":{"h":"כסנים","r":"KRU09619","alt":[],"source":"krupnik","glosses":[{"text":"linen-garments","label":""}],"html":"<p>כלי פשתן linen-garments  ירוש׳ פס׳ פ״י ל״ז ע״ב: נשים בראוי להן כגון כסנים ובוצלין.</p>","notation":["ז״ר","Source emendation: בִּיסְנִין"]},"39848":{"h":"כָּסַס","r":"KRU09620","alt":[],"source":"krupnik","glosses":[{"text":"to chew","label":""},{"text":"to be chewed","label":""}],"html":"<p>לעס to chew  תוס׳ בר׳ ד׳ ז׳: הכוסס את האורז. ִכְסַס  נפ׳, נלעס to be chewed  תוס׳ עוקצ׳ א׳ ב׳: של שובלין וכו׳ מפני שנכססין. </p>","notation":["פ״י"]},"39849":{"h":"כְּסַס","r":"KRU09621","alt":[],"source":"krupnik","glosses":[{"text":"to give to chew","label":""}],"html":"<p>עי׳ כָּסַס. יומא פ״א ע״ב: כס פילפלי וכו׳. אָכֵס  אפ׳, נתן ללעוס to give to chew  כת׳ ע״ז ע״א: אכסוהו שערי. </p>","notation":[]},"39850":{"h":"כַּסָּף","r":"KRU09622","alt":[],"source":"krupnik","glosses":[{"text":"silver-smith","label":""}],"html":"<p>צורף כסף silver-smith  תוס׳ סוכה ד׳ ו׳: ולא היו יושבין מעורבבין אלא זהבים בפני עצמן כספים בפני עצמן.</p>","notation":["ז׳"]},"39851":{"h":"כסף","r":"KRU09623","alt":[],"source":"krupnik","glosses":[{"text":"to grow pale","label":"נִכְסַף נפ׳,"},{"text":"to fall in value","label":"הִכְסִיף הפ׳, 2"},{"text":"to put to shame","label":"הִכְסִיף הפ׳, 3"}],"html":"<p>נִכְסַף נפ׳, נעשה חוור to grow pale  תוס׳ נדה ו׳ ד׳: משיכסף ראש החוטם.\nהִכְסִיף הפ׳, 1 כנ״ל. נדה מ״ז ע״א: משיכסיף ראש החוטם.\nהִכְסִיף הפ׳, 2 ירד מערכו to fall in value  ערכ׳ ל׳ ע״א: מכרה לו במנה והשביחה ועמדה על מאתים וכו׳ מכרה לו במאתים והכסיפה ועמדה על מנה.\nהִכְסִיף הפ׳, 3 בייש to put to shame  ירוש׳ יומא פ״ד מ״א ע״ד: זהב סגור שהיה מכסיף בעד כל הזהבים שהיו שם.</p>","notation":["Source marks no qal form"]},"39852":{"h":"כְּסַף","r":"KRU09624","alt":[],"source":"krupnik","glosses":[{"text":"to feel ashamed","label":""}],"html":"<p>התבייש to feel ashamed  ערכ׳ ט״ז ע״א: חס לי דליכסוף זרעיה דרב על ידאי.</p>","notation":["פ״ע"]},"39853":{"h":"כַּסֵּף","r":"KRU09625","alt":[],"source":"krupnik","glosses":[{"text":"to put to shame","label":"פַעל, 1"},{"text":"to reduce in value","label":"פַעל, 2"}],"html":"<p>פַעל, 1 בייש to put to shame  חג׳ ה׳ ע״א: מוטב דלא יהבת ליה מהשתא דיהבת ליה וכספתיה.\nפַעל, 2 גרם ירידת הערך to reduce in value  כת׳ ק״ד ע״ב: זימנין דאזלא ומשבחא להו ודבעלה מכספי.</p>","notation":[]},"39854":{"h":"כסף²","r":"KRU09626","alt":[],"source":"krupnik","glosses":[{"text":"to be put to shame","label":"אִתְכַּסֵּף, אִיכַּסַף אתפ׳,"}],"html":"<p>אִתְכַּסֵּף, אִיכַּסַף אתפ׳, נתבייש to be put to shame  תרג׳ איוב ו׳ כ׳ (באו עדיה ויחפרו): אתו לגבה ואתכסיפו; ב״ב קכ״ג ע״א: השתא מיכספא אחתאי.</p>","notation":["Source marks no qal form"]},"39855":{"h":"כְּסַפְתָּא","r":"KRU09627","alt":[],"source":"krupnik","glosses":[{"text":"money-chest","label":""}],"html":"<p>ארגז לשמירת כסף money-chest  ב״ק ס״ב ע״א: מי מנחי אנשי מרגניתא בכספתא או לא.</p>","notation":["נ׳"]},"39856":{"h":"כְּסַפְתִּיאַס","r":"KRU09628","alt":[],"source":"krupnik","glosses":[{"text":"a species of fish","label":""}],"html":"<p>מין דג a species of fish  תוס׳ צוק׳ חול׳ ג׳ כ״ז: בשעה שעולה מן המים כגון וכו׳ כספתיאס אכנס וכו׳.</p>","notation":["ז׳"]},"39857":{"h":"כָּעוּס","r":"KRU09632","alt":[],"source":"krupnik","glosses":[{"text":"angry","label":""}],"html":"<p>נרגז angry  דב״ר פ״ג: עשה עצמו כאילו כעוס על ישראל.</p>","notation":["ת׳"]},"39858":{"h":"כָּעוּר","r":"KRU09634","alt":[],"source":"krupnik","glosses":[{"text":"ugly","label":"1"},{"text":"strange","label":"2"}],"html":"<p>1 מאוס, מכוער ugly  נד׳ פ״ט מ״י: קונם שאיני נושא את פלונית כעורה והרי היא נאה.\n2 משונה, מוזר strange  חול׳ קט״ו ע״ב: כעורה זו ששנה רבי.</p>","notation":["ת׳"]},"39859":{"h":"כְּעִירוּת","r":"KRU09635","alt":[],"source":"krupnik","glosses":[{"text":"ugliness","label":""}],"html":"<p>מאוס, כיעור ugliness  אסת״ר א׳ ג׳: עשרה חלקים של נוי בעולם וכו׳ עשרה חלקים של כעירות בעולם.</p>","notation":["נ׳"]},"39860":{"h":"כַּעַךְ","r":"KRU09636","alt":[],"source":"krupnik","glosses":[{"text":"bretzel","label":""}],"html":"<p>מאפה בצורת עיגול bretzel  פס׳ מ״ח ע״ב: לא שני אלא כיכרות של בבל וכו׳ אבל כעכין לא.</p>","notation":["ז׳"]},"39861":{"h":"כִּעְכַּע","r":"KRU09637","alt":[],"source":"krupnik","glosses":[{"text":"to cough","label":""}],"html":"<p>השתעל to cough  ויק״ר פכ״א: הוה מכעכע על שום ונשמע קולו.</p>","notation":["פ״ע"]},"39862":{"h":"כָּעַס","r":"KRU09639","alt":[],"source":"krupnik","glosses":[{"text":"to fly into a rage","label":"הִתְכָּעֵס התפ׳,"}],"html":"<p>הִתְכָּעֵס התפ׳, בא לכלל כעס to fly into a rage  ב״ר פכ״ז: למלך שבנה פלטין ע״י אדרכל ראה אותה ולא ערבה לו על מי יש לו להתכעס לא על ארדכל.</p>","notation":["Marked biblical in source"]},"39863":{"h":"כער","r":"KRU09640","alt":[],"source":"krupnik","glosses":[{"text":"to become ungainly","label":"הִתְכָּעֵר התפ׳,"}],"html":"<p>הִתְכָּעֵר התפ׳, נעשה מאוס ומכוער to become ungainly  ב״ר פי״ז: ועל ידי שגדלתי עמו בבית התכערתי בעיניו.</p>","notation":["Source marks no qal form"]},"39864":{"h":"כ״ף","r":"KRU09643","alt":[],"source":"krupnik","glosses":[{"text":"the eleventh letter of the Alphabet","label":""}],"html":"<p>אות אחת־עשרה באלפבית the eleventh letter of the Alphabet  ויק״ר פי״ט: אם אתה עושה בי״ת כ״ף וכו׳.</p>","notation":[]},"39865":{"h":"כַּף","r":"KRU09644","alt":[],"source":"krupnik","glosses":[{"text":"spoon","label":"1"},{"text":"glove","label":"2"},{"text":"scale of the balance","label":"3"}],"html":"<p>1 בית קבול לשאיבת מרק וכדומה spoon  כל׳ פי״ג מ״ב; זומא לסטרה שניטלה כפה טמאה מפני המזלג ניטל המזלג טמאה מפני כפה.\n2 נעל יד glove  כל׳ פכ״ו מ״ג: כף לוקטי קוצים.\n3 קערת המאזנים scale of the balance  אבות פ״ח מ״ח: אם יהיו כל חכמי ישראל בכף מאזנים ור״א בן הורקנוס בכף שניה מכריע את כולם.</p>","notation":["Marked biblical in source"]},"39866":{"h":"כַּף שֶׁל סַיָּידִין","r":"KRU09645","alt":[],"source":"krupnik","glosses":[{"text":"the mason’s trowel","label":""}],"html":"<p>בית קבול שהסייד לוקח בו סיד וכדומה the mason’s trowel  שבת פ׳ ע״ב: כדי ליתן על פי כף של סיידין.</p>","notation":[]},"39867":{"h":"כַּפָּא","r":"KRU09646","alt":[],"source":"krupnik","glosses":[{"text":"spoon trowel","label":"1"},{"text":"bundle","label":"2"},{"text":"branch","label":"3"},{"text":"the Greek letter Kappa","label":"4"}],"html":"<p>1 כף, בית קבול spoon trowel  פס׳ כ״ח ע״א: כפא דחטא נגרא.\n2 חבילה bundle  נד׳ מ״ח ע״ב: כפי דכיתנא.\n3 ענף branch  סוכה ל״ב ע״א: ואימא תרתי כפי דתמרי.\n4 שם אות יונית the Greek letter Kappa  איכ״ר א׳ א׳: כפא בלשון יון עשרים.</p>","notation":["ז׳"]},"39868":{"h":"כַּפָּא דְמוֹחָא","r":"KRU09647","alt":[],"source":"krupnik","glosses":[{"text":"skull","label":""}],"html":"<p>כפת הגלגולת skull  חול׳ כ״ד ע״א: מכפא דמוחא ועד אטמא.</p>","notation":[]},"39869":{"h":"כְּפָאת","r":"KRU09649","alt":[],"source":"krupnik","glosses":[{"text":"strap","label":""}],"html":"<p>קשור strap  אסת״ר א׳ ו׳: היו מכופתין בכפאתין של כסף.</p>","notation":["ז׳"]},"39870":{"h":"כָּפָה","r":"KRU09650","alt":[],"source":"krupnik","glosses":[{"text":"to force","label":""},{"text":"to invert","label":""},{"text":"to be inverted","label":""},{"text":"to be epileptic","label":""}],"html":"<p>1) הכריח to force  תוס׳ ב״ב ט׳ י״ג: וכופין את היורשין לקיים דברי המת. 2) הפך to invert  כל׳ פ״ז מ״ג: הכופה את הסל ועושה על גביו כירה. נִכְפָּה נפ׳, 1) נהפך to be inverted  ירוש׳ בר׳ פ״ג ה׳ ע״ד: דרגש נזקפת ואינה נכפית. 2) היה חולה נופל to be epileptic  פס׳ קי״ב ע״ב: אותו תינוק נכפה. </p>","notation":["Marked biblical in source"]},"39871":{"h":"כֵּפָה","r":"KRU09652","alt":[],"source":"krupnik","glosses":[{"text":"a plant","label":""}],"html":"<p>כֵּפַת הַמֶּרְחָץ מין צמח a plant  תוס׳ צוק׳ דמ׳ א׳ נ״ט: כפת המרחץ פטורה מן הודאי ואין צריך לומר מן הדמאי.</p>","notation":["נ׳"]},"39872":{"h":"כְּפוּי טוֹבָה","r":"KRU09653","alt":[],"source":"krupnik","glosses":[{"text":"ungrateful","label":""}],"html":"<p>שאינו מכיר תודה ungrateful  ויק״ר פ״ד: ג׳ כפויי טובה הן הארץ והאשה והנפש הארץ שנאמר ארץ לא שבעה מים וכו׳.</p>","notation":["ת׳"]},"39873":{"h":"כָּפוּן","r":"KRU09654","alt":[],"source":"krupnik","glosses":[{"text":"eager for","label":""}],"html":"<p>להוט אחרי־ eager for  ב״ר פע״ט: זה לבן שבא כפון על ממונו של יעקב לשודדו.</p>","notation":["ת׳"]},"39874":{"h":"כְּפוּנִי","r":"KRU09655","alt":[],"source":"krupnik","glosses":[{"text":"date-berry in its early stage","label":""}],"html":"<p>תמר קשה date-berry in its early stage  ירוש׳ ב״ק פ״ו ה׳ ע״ב: חד בר נש גנב חדא כפוני.</p>","notation":["נ׳"]},"39875":{"h":"כְּפוּסַאי","r":"KRU09656","alt":[],"source":"krupnik","glosses":[{"text":"a man’s name","label":""}],"html":"<p>a man’s name  שבת קמ״ז ע״א: יהושע בן כפוסאי היה חתנו של ר״ע. </p>","notation":["שם איש"]},"39876":{"h":"כָּפַוּשׁ","r":"KRU09657","alt":[],"source":"krupnik","glosses":[{"text":"ungainly","label":""}],"html":"<p>מכוער ungainly  ילק׳ איוב תתקי״ז: יש אדם בחור ואשתו מכוערת וכו׳ ואומרים אבוד הבחור הזה על הכפושה הזו.</p>","notation":["ת׳"]},"39877":{"h":"כָּפוּת","r":"KRU09658","alt":[],"source":"krupnik","glosses":[{"text":"tied","label":"1"},{"text":"bandage","label":"2"}],"html":"<p>1  tied  ויק״ר פ״ל: יצחק שהיה כפות ועקוד על גבי המזבח.\n2  bandage  פסיק״ר פל״א: כפותינו חזקים.\n3 עי׳ קָבוּת. תוס׳ צוק׳ כל׳ ב״ק ז׳ ז׳: כפותין של מורייס שגפסן עם השפה. </p>","notation":[]},"39878":{"h":"כְּפִי","r":"KRU09659","alt":[],"source":"krupnik","glosses":[{"text":"to bend","label":""},{"text":"to force","label":""}],"html":"<p>1) עי׳ כָּפָה 2. ירוש׳ חג׳ פ״ב ע״ז ע״ד: וכפונון על ראשיהון. 2) עי׳ כָּפָה 1. ירוש׳ גיט׳ פ״א מ״ג ע״ב: כפוניה ויהב לה חורן. אַכְפֵּי  אפ׳, 1) כפף to bend  ב״ב ד׳ ע״א: אכפיה ליה לקרנא לבר. 2) הכריח to force  שם ח׳ ע״ב: רבא אכפיה לר׳ נתן בר אמי ושקיל מיניה ד׳ מאה זוזי לצדקה. אִיתְכְּפִי אתפ׳, עי׳ נִכְפָּה 1. ירוש׳ ע״ז פ״ג מ״ב ע״ג: איתכפון אנדרטייא וכו׳ איתכפון איקונייא. </p>","notation":["פ״י"]},"39879":{"h":"כְּפִיָּיה","r":"KRU09660","alt":[],"source":"krupnik","glosses":[{"text":"inverting","label":""}],"html":"<p>הפיכה inverting  תוס׳ מו״ק ב׳ ט׳: כפיית המטה.</p>","notation":["נ׳"]},"39880":{"h":"כָּפֵיל","r":"KRU09661","alt":["כְּפֵילָא","כְּפֵילָה"],"source":"krupnik","glosses":[{"text":"doubling","label":""}],"html":"<p>כפל, משנה doubling  ב״ק ס״ה ע״א: משלם תשלומי כפל ואשם וחומשו עולה לו בכפילו; שם: כפילא ארבעה וחומשא זוזא: ירוש׳ ב״ב פ״ח ט״ז ע״ב: לענין כפילה.</p>","notation":["ז׳"]},"39881":{"h":"כְּפִין","r":"KRU09662","alt":["כְּפִינָא"],"source":"krupnik","glosses":[{"text":"hungry","label":""}],"html":"<p>רעב hungry  בר׳ נ״ח ע״ב: כל דהוה עייל כפין נפיק כי שבע; תרג׳ תה׳ ק״ז ט׳ (נפש רעבה): נפשא כפינא.</p>","notation":[]},"39882":{"h":"כָּפִיס","r":"KRU09663","alt":[],"source":"krupnik","glosses":[{"text":"mason’s trowel","label":""}],"html":"<p>כף הסיידים mason’s trowel  מדות פ״ג מ״ד: לא היו סדין אותן בכפיס של ברזל.</p>","notation":["Marked biblical in source"]},"39883":{"h":"כְּפִיפָה","r":"KRU09664","alt":[],"source":"krupnik","glosses":[{"text":"a basket made of palm twigs","label":"1"},{"text":"bending","label":"2"}],"html":"<p>1 סל עשוי מלולבים a basket made of palm twigs \n2 פעולת הכופף bending  סנה׳ ס״ה ע״א: כפיפת קומתו.</p>","notation":["נ׳"]},"39884":{"h":"כְּפִירָה","r":"KRU09665","alt":[],"source":"krupnik","glosses":[{"text":"denial","label":""}],"html":"<p>הכחשה denial  ב״מ ל״ו ע״א: כפירת ממון.</p>","notation":["נ׳"]},"39885":{"h":"כְּפִּישָׁא","r":"KRU09666","alt":["כְּפִישָׁה"],"source":"krupnik","glosses":[{"text":"a basket","label":""}],"html":"<p>מין סל a basket  גיט׳ ס״ב ע״א: בכפישא או באנחותא; אהל׳ פ״ה מ״ו: כוורת פתוחה וכפישה נתונה עליה.</p>","notation":[]},"39886":{"h":"כְּפִיתָה","r":"KRU09668","alt":[],"source":"krupnik","glosses":[{"text":"binding","label":""}],"html":"<p>קשירה binding  כל׳ פי״ב מ״א: שלשלת וכו׳ העשויה לכפיתה.</p>","notation":["נ׳"]},"39887":{"h":"כָּפַל","r":"KRU09669","alt":[],"source":"krupnik","glosses":[{"text":"to double","label":""}],"html":"<p>עשה או נתן פי שנים to double  ירוש׳ יומא פ״ג מ״א ע״א: שלחו אחריהם ולא רצו לבוא עד שכפלו להן שכרן שנים עשר מנה היו נוטלין ונתנו להן עשרים וארבע.</p>","notation":["Marked biblical in source"]},"39888":{"h":"כִּפֵּל","r":"KRU09670","alt":[],"source":"krupnik","glosses":[{"text":"to fold","label":"הִכְפִּיל הפ׳,"}],"html":"<p>פיעל, כנ״ל. מנח׳ פ״ו מ״ד: כופל אחת לשנים ושנים לארבעה וכו׳ מנחת כהן המשיח לא היה מכפלה. \nהִכְפִּיל הפ׳, קיפל to fold  ירוש׳ נד׳ פ״ח מ״ד: עד שיכפילו המקצועות.</p>","notation":[]},"39889":{"h":"כְּפַל","r":"KRU09671","alt":[],"source":"krupnik","glosses":[{"text":"to be folded up","label":""},{"text":"to be doubled","label":""},{"text":"to take the trouble","label":""}],"html":"<p>עי׳ כָּפַל. גיט׳ ס״ב ע״א: דכפלינן שלמא. אִתְכְּפֵל אתפ׳, 1) התקפל to be folded up  תרג׳ יש׳ ל״ח י״ב: אתכפילו כמשכנא דרעי. 2) נכפל to be doubled  תרג׳ יח׳ כ״א י״ט (ותכפל חרב): ותתכפיל חרבא. אִיכְּפִיל אתפ׳, 1) כנ״ל 2. ב״מ ק״ד ע״ב: אי מיקנא לא מיכפל. 2) טרח to take the trouble  שבוע׳ מ״ח ע״ב: איכפלי ואתאי. </p>","notation":[]},"39890":{"h":"כֶּפֶל","r":"KRU09672","alt":[],"source":"krupnik","glosses":[{"text":"doubling, double amount","label":""}],"html":"<p>משנה, פי שנים doubling, double amount  סנה׳ פ״א מ״א: תשלומי כפל ותשלומי ארבעה וחמשה.</p>","notation":["ז׳"]},"39891":{"h":"כִּפְלָא","r":"KRU09673","alt":[],"source":"krupnik","glosses":[{"text":"winding road","label":"1"},{"text":"loin","label":"2"}],"html":"<p>1 עקוב, שביל עקוס winding road  תרּג׳ יש׳ מ׳ ד׳ (והיה העקוב למישור): ויהי כפלא למישרא.\n2 כסל loin  תרג׳ איוב ט״ו כ״ז (פימה עלי כסל): רוטבא עילוי כפלא.</p>","notation":["ז׳"]},"39892":{"h":"כַּפְלִיּוֹת","r":"KRU09675","alt":[],"source":"krupnik","glosses":[{"text":"a species of figs","label":""}],"html":"<p>מין תאנים a species of figs  ב״ר פצ״ח: כפליות ואנפקינון.</p>","notation":["נ״ר"]},"39893":{"h":"כְּפַן","r":"KRU09677","alt":[],"source":"krupnik","glosses":[{"text":"to bend","label":""},{"text":"to be hungry","label":""},{"text":"to cause to hunger","label":""}],"html":"<p>1) כפף to bend  תרג׳ איוב מ׳ י״ז (יחפץ זנבו): כפין דונביה. 2) רעב to be hungry  בר׳ ס״ב ע״ב: עד דכפנת אכול. אַכְפֵּן אפ׳, הרעיב to cause to hunger  שבת ל״ג ע״א: מכפין נפשיה. </p>","notation":["פ״י"]},"39894":{"h":"כְּפַן²","r":"KRU09678","alt":["כַּפְנָא"],"source":"krupnik","glosses":[{"text":"hunger","label":""}],"html":"<p>רעב hunger  תרג׳ רות א׳ א׳ (רעב): כפן תקיף; תענ׳ ח׳ ע״ב: אמותנא וכפנא.</p>","notation":[]},"39895":{"h":"כַּפְנָאֵי","r":"KRU09679","alt":[],"source":"krupnik","glosses":[{"text":"a dish of date-berries","label":""}],"html":"<p>מין מאכל מתמרים a dish of date-berries  אסת״ר א׳ ד׳: מאן דאמר קנרס ומאן דאמר כפנאי.</p>","notation":["ז״ר"]},"39896":{"h":"כָּפְנִיּוֹת","r":"KRU09680","alt":["כָּפְנִיָיתָא"],"source":"krupnik","glosses":[{"text":"the inflorescence of palms","label":""}],"html":"<p>פרי בוסר של תמר the inflorescence of palms  תוס׳ מעש״ש א׳ י״ד: כפניות הרי הן כפרי; בכורות י״ח ע״א: אדאכלת כפנייתא וכו׳.</p>","notation":[]},"39897":{"h":"כְּפַס","r":"KRU09681","alt":[],"source":"krupnik","glosses":[{"text":"to tie, to fasten","label":""}],"html":"<p>קשר, הדק to tie, to fasten  תרג׳ אס׳ א׳ ו׳ (אחוז וגו׳ על גלילי כסף ועמודי שש): כפיסן עילוי עמודי מרמרין.</p>","notation":["פ״י"]},"39898":{"h":"כָּפֵס","r":"KRU09682","alt":[],"source":"krupnik","glosses":[{"text":"beam, lath","label":""}],"html":"<p>כפיס, חתיכת עץ beam, lath  תוס׳ צוק׳ עיר׳ ט׳ (ו׳), ט״ז: מיעטו באבנים ובכפסים.</p>","notation":["ז׳"]},"39899":{"h":"כפע","r":"KRU09683","alt":[],"source":"krupnik","glosses":[{"text":"to be shattered","label":"אתכפע [אִתְכְפַע] אתפ׳,"}],"html":"<p>אתכפע [אִתְכְפַע] אתפ׳, התפוצץ to be shattered  תרג׳ דהי״ב ל״ג י״ג: ואתכפעת מולתא.</p>","notation":["Source marks no qal form"]},"39900":{"h":"כָּפַף","r":"KRU09684","alt":[],"source":"krupnik","glosses":[{"text":"to force","label":""},{"text":"to upset","label":""},{"text":"to be bent","label":""}],"html":"<p>1) הכריח to force  ירוש׳ נזיר פ״ט נ״ז ע״ג: בשכפפו רבו או בשלא כפפו רבו. 2) הפך to upset  ירוש׳ בר׳ פ״ג ו׳ ע״א: מטות כפופות. נִכְפַּף נפ׳, נעשה כפוף ונטוי to be bent  פסיק״ר כ״ח: עד שנכפפת קומתם מפני המשאוי. </p>","notation":["Marked biblical in source"]},"39901":{"h":"כָּפַר","r":"KRU09685","alt":[],"source":"krupnik","glosses":[{"text":"to deny","label":""}],"html":"<p>כחש וכחד to deny  שבוע׳ פ״ו מ״ג: טענו כלים וקרקעות והודה בכלים וכפר בקרקעות.</p>","notation":["Marked biblical in source"]},"39902":{"h":"כָּפַר בְּעִיקָר","r":"KRU09686","alt":[],"source":"krupnik","glosses":[{"text":"to deny the unity of God","label":""},{"text":"to contradict","label":""}],"html":"<p>לא האמין באחדות הבורא to deny the unity of God  ב״ב ט״ז ע״ב: וכפר בעיקר וכפר בתחיית המתים. הִכְפִּיר הפ׳, הכחיש to contradict  פס׳ ס״ט ע״א: אל תכפירני בשעת הדין כך מקובלני ממך. </p>","notation":[]},"39903":{"h":"כָּפָר","r":"KRU09687","alt":[],"source":"krupnik","glosses":[{"text":"prefixed to numerous names of places in Palestine","label":""}],"html":"<p>(נוסף לשמות כמה מקומות בארץ ישראל) prefixed to numerous names of places in Palestine </p>","notation":["Marked biblical in source"]},"39904":{"h":"כְּפַר נַחוּם","r":"KRU09701","alt":[],"source":"krupnik","glosses":[{"text":"Capernaum","label":""}],"html":"<p>Capernaum  קהל״ר ז׳ כ״ו: וחוטא אלו בני כפר נחום; </p>","notation":[]},"39905":{"h":"כַּפְרָא","r":"KRU09716","alt":[],"source":"krupnik","glosses":[{"text":"sediments","label":"1"},{"text":"name of a place in Palestine","label":"2"}],"html":"<p>1 שיירים, פסולת sediments  ב״ק ק״א ע״א: כפרא דודי.\n2 שם מקום בארץ ישראל name of a place in Palestine  ירוש׳ סנה׳ פ״ו כ״ג ע״ד: ר׳ מני הורי לר׳ לא דכפרא.</p>","notation":["ז׳"]},"39906":{"h":"כַּפָּרָה","r":"KRU09718","alt":[],"source":"krupnik","glosses":[{"text":"atonement","label":""},{"text":"expiatory sacrifice","label":""},{"text":"an expression of love and respect","label":""},{"text":"an expression of respect with regard to a dead person","label":""}],"html":"<p>1) כסוי חטא וביטולו atonement  סנה׳ פ״ו מ״ב: תהא מיתתי כפרה על כל עוונותי. 2) קרבן של כפרה expiatory sacrifice  הור׳ פ״א מ״ב: בין שהביאו כפרתן וכו׳. אֲנִי כַּפָּרָתוֹ דיבור של חבה וכבוד an expression of love and respect  נגע׳ פ״ב מ״א: בני ישראל אני כפרתן וכו׳. הֲרֵינִי כַּפָּרַת מִשְׁכָּבוֹ דיבור של כבוד לזכר מת חשוב an expression of respect with regard to a dead person  קיד׳ ל״א ע״ב: כך אמר אבא מרי הריני כפרת משכבו. </p>","notation":["נ׳"]},"39907":{"h":"כַּפְרוֹנָא","r":"KRU09719","alt":[],"source":"krupnik","glosses":[{"text":"village","label":""}],"html":"<p>כפר village  תרג׳ שני אס׳ ט׳ י״ט (ערי הפרזות): כפרוניא.</p>","notation":["ז׳"]},"39908":{"h":"כַּפְרוּסָאָה","r":"KRU09720","alt":[],"source":"krupnik","glosses":[{"text":"of Cyprus","label":""}],"html":"<p>איש קפריסין of Cyprus  תרג׳ ירוש׳ בר׳ י׳ י״ז (סיני): כפרוסאי.</p>","notation":["ת׳"]},"39909":{"h":"כַּפְרִי","r":"KRU09721","alt":[],"source":"krupnik","glosses":[{"text":"name of a place in Babylonia","label":""}],"html":"<p>בבבל name of a place in Babylonia  סנה׳ ה׳ ע״א: אבא בר אחא כרסלא מכפרי.</p>","notation":["שם מקום"]},"39910":{"h":"כַּפְרִימִין","r":"KRU09722","alt":[],"source":"krupnik","glosses":[{"text":"a kind of cakes","label":""}],"html":"<p>מין תופינים a kind of cakes  שהש״ר א׳ ט״ו: נקרונות וכפרימין.</p>","notation":["ז״ר"]},"39911":{"h":"כַּפְרָן","r":"KRU09723","alt":[],"source":"krupnik","glosses":[{"text":"liar","label":""}],"html":"<p>שקרן liar  שבוע׳ מ״א ע״ב: הוחזק כפרן.</p>","notation":["ז׳"]},"39912":{"h":"כַּפְרָנָא","r":"KRU09724","alt":[],"source":"krupnik","glosses":[{"text":"village","label":""}],"html":"<p>כפר village  תרג׳ במ׳ ל״ב מ״א (חות): כפרני.</p>","notation":["ז׳"]},"39913":{"h":"כַּפְרָנוּת","r":"KRU09725","alt":["כַּפְרָנִית"],"source":"krupnik","glosses":[{"text":"denial","label":""}],"html":"<p>כפירה והכחשה denial  ירוש׳ גיט׳ פ״ה מ״ו ע״ג: מלוה שנעשית בו כפרנות אינה נשמטת; שבי׳ פ״י ל״ט ע״ג: מלוה שהיא נעשית כפרנית.</p>","notation":[]},"39914":{"h":"כָּפַת","r":"KRU09727","alt":[],"source":"krupnik","glosses":[{"text":"to tie","label":""},{"text":"to be tied","label":""}],"html":"<p>קשר ואסר to tie  מכות פ״ג סי״ב: כיצד מלקין אותו כופת שתי ידיו על העמוד הילך והילך וכו׳. נִכְפַּת נפ׳, נקשר ונאסר to be tied  שהש״ר א׳ י״ד: זה יצחק שנכפת על המזבח. </p>","notation":["פ״י"]},"39915":{"h":"כְּפָתָא","r":"KRU09730","alt":[],"source":"krupnik","glosses":[{"text":"tie","label":""}],"html":"<p>קשור tie  ילק׳ נחום תקס״א: ישתריין יתהון כפתא.</p>","notation":["ז׳"]},"39916":{"h":"כָּפָתָה","r":"KRU09731","alt":[],"source":"krupnik","glosses":[{"text":"bundle","label":""}],"html":"<p>צרור, חבילה bundle  ב״ר פ״ק: קשרי כפתותיהן התירו.</p>","notation":["נ׳"]},"39917":{"h":"כַּפְתּוֹר","r":"KRU09732","alt":[],"source":"krupnik","glosses":[{"text":"well and nicely said!","label":""}],"html":"<p>כַּפְתּוֹר וָפֶרַח יפה דרשת! well and nicely said!  ב״ר פצ״א: בשעה שהיה אדם אומר דבר מתוקן לפני ר׳ טרפון היה אומר כפתור ופרח וכו׳.</p>","notation":["Marked biblical in source"]},"39918":{"h":"כְּצוּצְרָה","r":"KRU09734","alt":[],"source":"krupnik","glosses":[{"text":"castle","label":""}],"html":"<p>מבצר castle  פסיק״ר ט״ו: אהלים וכצוצריות.</p>","notation":["נ׳"]},"39919":{"h":"כְּרָא","r":"KRU09741","alt":[],"source":"krupnik","glosses":[{"text":"to dig","label":""}],"html":"<p>חפר to dig  ב״ק נ״א ע״א: זיל כרי לן ואזל כרא להו.</p>","notation":["פ״י"]},"39920":{"h":"כְּרַב","r":"KRU09742","alt":[],"source":"krupnik","glosses":[{"text":"to plough","label":""},{"text":"to tie around","label":""}],"html":"<p>חרש to plough  ב״ק צ״ו ע״ב: כרב בהו כרבא. אַכְרֵב  אפ׳, ענד וקשר to tie around  תרג׳ איוב ל״א ל״ו (אענדנו עטרות לי): אכרביניה בלילן לי. </p>","notation":["פ״י"]},"39921":{"h":"כְּרָבָא","r":"KRU09743","alt":[],"source":"krupnik","glosses":[{"text":"ploughing","label":""}],"html":"<p>חרישה ploughing  ב״ב י״ב ע״א: יומא דכרבא.</p>","notation":["ז׳"]},"39922":{"h":"כַּרְבָּא","r":"KRU09744","alt":[],"source":"krupnik","glosses":[{"text":"cabbage","label":""}],"html":"<p>כרוב cabbage  גיט׳ ס״ט ע״ב: קלחי כרבא.</p>","notation":["ז׳"]},"39923":{"h":"כָּרַבְלִין","r":"KRU09745","alt":[],"source":"krupnik","glosses":[{"text":"dancers","label":""}],"html":"<p>מחוללים dancers  ב״ר פ״נ: אדרבלין וכרבלין.</p>","notation":["ז״ר"]},"39924":{"h":"כַּרְבֶּלֶת","r":"KRU09746","alt":[],"source":"krupnik","glosses":[{"text":"the crest of the cock","label":""}],"html":"<p>כמין מסרק אדום שבראש התרנגול the crest of the cock  שבת ק״י ע״ב: הרוצה שיסרס תרנגול יטול כרבלתו ומסתרס מאליו.</p>","notation":["נ׳"]},"39925":{"h":"כַּרְבַּלְתָּא","r":"KRU09747","alt":[],"source":"krupnik","glosses":[{"text":"a kind of cloak","label":"2"}],"html":"<p>1 כנ״ל. עיר׳ ק׳ ע״ב: לישמטיה לכרבלתה דתרנגול. \n2 מין מלבוש a kind of cloak  בר׳ כ׳ ע״א: לההיא כותית דהות לבישא כרבלתא.</p>","notation":["ז׳"]},"39926":{"h":"כַּרְגָּא","r":"KRU09748","alt":[],"source":"krupnik","glosses":[{"text":"tax, tribute","label":""}],"html":"<p>מס tax, tribute  סנה׳ ק״ט ע״א: קא מובילנא כרגא לקיסר.</p>","notation":["ז׳"]},"39927":{"h":"כַּרְדּוּט","r":"KRU09749","alt":[],"source":"krupnik","glosses":[{"text":"a tunic with sleeves","label":""}],"html":"<p>כתונת בעלת שרוולים a tunic with sleeves  תרג׳ ש״ב י״ג י״ח (מעילים): כרדוטין.</p>","notation":["ז׳"]},"39928":{"h":"כרדוכאות","r":"KRU09750","alt":[],"source":"krupnik","glosses":[{"text":"vessels containing lustral water","label":""}],"html":"<p>מזרקי מים קדושים vessels containing lustral water  ספרי במ׳ קנ״ח: הכרדוכאות והכוסות והקיתונות וכו׳.</p>","notation":["נ״ר","Source emendation: כַּרְנִיבָּאוֹת"]},"39929":{"h":"כַּרְדִּיטִין","r":"KRU09751","alt":[],"source":"krupnik","glosses":[{"text":"bread made of groats","label":""}],"html":"<p>לחם גריסים bread made of groats  תרג׳ ירמ׳ מ״ד י״ט (בונים): כרדיטין.</p>","notation":["ז״ר"]},"39930":{"h":"כְּרַהּ","r":"KRU09752","alt":[],"source":"krupnik","glosses":[{"text":"to shrink","label":""}],"html":"<p>התכווץ to shrink  נזיר ל״ד ע״ב: ענבי דכרין.</p>","notation":["פ״ע"]},"39931":{"h":"כרו משא","r":"KRU09753","alt":[],"source":"krupnik","glosses":[{"text":"service-tree","label":""}],"html":"<p>מין אילן service-tree  פסח׳ קי״א ע״ב: כל דקשי סילויה קשי טוליה לבר מכרו משא אע״ג דקשי סילויה לא קשי טוליה.</p>","notation":["ז׳","Source emendation: כְּרוּמְשָׁא"]},"39932":{"h":"כְּרוּב","r":"KRU09754","alt":[],"source":"krupnik","glosses":[{"text":"cabbage","label":""}],"html":"<p>מין ירק cabbage  שבי׳ פ״ט מ״א: חוץ מספיחי כרוב שאין כיוצא בהן בירקות שדה.</p>","notation":["ז׳"]},"39933":{"h":"כְּרוֹבָא","r":"KRU09755","alt":[],"source":"krupnik","glosses":[{"text":"a certain measure of land","label":""}],"html":"<p>כברת ארץ a certain measure of land  תרג׳ בר׳ ל״ה ט״ז (כברת ארץ): כרוב ארעא.</p>","notation":["ז׳"]},"39934":{"h":"כְּרוּז","r":"KRU09757","alt":[],"source":"krupnik","glosses":[{"text":"proclamation","label":""}],"html":"<p>קול קורא, פרסום proclamation  יבמ׳ ל״ו ע״א: ונמצא אתה מצריכה כרוז לכהונה.</p>","notation":["ז׳"]},"39935":{"h":"כָּרוֹז","r":"KRU09758","alt":["כָּרוֹזָא"],"source":"krupnik","glosses":[{"text":"public crier","label":""}],"html":"<p>שליח להכרזה בפומבי public crier  סנה׳ פ״ו מ״א: יוצא ליסקל וכרוז יוצא לפניו איש פלוני בן פלוני יוצא וכו׳; ירוש׳ שקל׳ פ״ה מ״ה ע״ד: אכריז כרוזא.</p>","notation":[]},"39936":{"h":"כָּרַוְיָא","r":"KRU09759","alt":[],"source":"krupnik","glosses":[{"text":"caravay","label":""}],"html":"<p>כמון caravay  ע״ז נ״ט ע״א: מייתי כמונא כרויא.</p>","notation":["ז׳"]},"39937":{"h":"כָּרוּךְ","r":"KRU09760","alt":[],"source":"krupnik","glosses":[{"text":"twined around","label":"1"},{"text":"joined","label":"2"}],"html":"<p>1 מפותל ומחותל twined around  בר׳ פ״ה מ״א: נחש כרוך על עקבו.\n2 מחובר joined  ספרי דב׳ מ׳: ככר ומקל ירדו כרוכים מן השמים.</p>","notation":["ת׳"]},"39938":{"h":"כָּרוּךְ אַחֲרֵי","r":"KRU09761","alt":[],"source":"krupnik","glosses":[{"text":"clinging to","label":""}],"html":"<p>דבוק ונמשך clinging to  … חול׳ ע״ח ע״ב: שבנו כרוך אחריו.</p>","notation":[]},"39939":{"h":"כְּרוּךְ","r":"KRU09762","alt":[],"source":"krupnik","glosses":[{"text":"priestly division","label":""}],"html":"<p>משמר כהונה priestly division  תרג׳ יב״ע דב׳ י״ח ו׳: וייתי בכל כרוך דרעיא נפשיה.</p>","notation":["ז׳"]},"39940":{"h":"כְּרוּכָא","r":"KRU09763","alt":["כְּרוּכָה"],"source":"krupnik","glosses":[{"text":"winding","label":""}],"html":"<p>מֵעה winding  ויק״ר פ״ג: כרוכא קטינא כרוכא עבה; ירוש׳ ר״ה פ״א נ״ז ע״ב: אפסק כרוכה ודמך.</p>","notation":[]},"39941":{"h":"כְּרוּכָה עָבָה","r":"KRU09764","alt":[],"source":"krupnik","glosses":[{"text":"the large winding (jejunum)","label":""}],"html":"<p>מעי העבה the large winding (jejunum)  ילק׳ קהל׳ תתקע״ו: ומכרוכה עבה לכנת מעיא.</p>","notation":[]},"39942":{"h":"כְּרוּכָה קְטִינָא","r":"KRU09765","alt":[],"source":"krupnik","glosses":[{"text":"small winding (duodenum)","label":""}],"html":"<p>מעה הדק small winding (duodenum)  ילק׳ קהל׳ תתקע״ו: ומאסטומכא לכרוכא קטינא וכו׳.</p>","notation":[]},"39943":{"h":"כְּרוּכְיָא","r":"KRU09766","alt":[],"source":"krupnik","glosses":[{"text":"crane","label":""}],"html":"<p>מין עוף crane  קיד׳ מ״ד ע״א: צווח ריש לקיש כי כרוכיא.</p>","notation":["ז׳"]},"39944":{"h":"כְּרוּם","r":"KRU09767","alt":[],"source":"krupnik","glosses":[{"text":"a bird","label":"1"},{"text":"change of colours (with excitement)","label":"2"}],"html":"<p>1 מין עוף a bird  בר׳ ו׳ ע״א: עוף אחד יש בכרכי הים וכרום שמו.\n2 חלופי גוון הפנים מחמת התרגשות change of colours (with excitement)  שהש״ר א׳ י״ד: יעקב שנכנס בכרום פניו מתפחד וכו׳.</p>","notation":["ז׳"]},"39945":{"h":"כְּרוּם יַמָּה","r":"KRU09768","alt":[],"source":"krupnik","glosses":[{"text":"aquamarine","label":""}],"html":"<p>מין אבן טובה aquamarine  תרג׳ שמ׳ כ״ח כ׳ (תרשיש): כרום ימא.</p>","notation":[]},"39946":{"h":"כְּרוּסְפְּדָא","r":"KRU09769","alt":[],"source":"krupnik","glosses":[{"text":"fringe","label":""}],"html":"<p>ציצית fringe  תרג׳ דב׳ כ״ב י״ב (גדלים תעשה לך): כרוספדין תעביד לך.</p>","notation":["ז׳"]},"39947":{"h":"כְּרוּסְפְּדַאי","r":"KRU09770","alt":[],"source":"krupnik","glosses":[{"text":"name of an Amora","label":""}],"html":"<p>שם אמורא name of an Amora  סנה׳ ס״ט ע״א: אמר ר׳ כרוספדאי אמר ר׳ שבתאי.</p>","notation":["ז׳"]},"39948":{"h":"כְּרוֹפְיָיתָא","r":"KRU09771","alt":[],"source":"krupnik","glosses":[{"text":"dealer in vegetables","label":""}],"html":"<p>מוכרי ירקות dealer in vegetables  מו״ק י״ג ע״ב: כרופייתא דפומבדיתא.</p>","notation":["ז״ר"]},"39949":{"h":"כְּרוּשְׁתֵּינָא","r":"KRU09772","alt":[],"source":"krupnik","glosses":[{"text":"a species of bats","label":""}],"html":"<p>מין עטלף a species of bats  שבת ע״ח ע״א: דמא דכרושתינא.</p>","notation":["נ׳"]},"39950":{"h":"כָּרַז","r":"KRU09773","alt":[],"source":"krupnik","glosses":[{"text":"to call out, to announce","label":"הִכְרִיז הפ׳"}],"html":"<p>הִכְרִיז הפ׳ קרא בקול, פרסם to call out, to announce  דב״ר פ״ד: איקוניא מהלכת לפני האדם והכרוזות כורזין לפניו; ב״מ פ״ד מ״ז: והמוצא שוה פרוטה חייב להכריז.</p>","notation":["פ״י"]},"39951":{"h":"כְּרָזָא","r":"KRU09775","alt":[],"source":"krupnik","glosses":[{"text":"a species of locusts","label":""}],"html":"<p>מין ארבה a species of locusts  חול׳ ס״ב ע״ב: כרזא דבי חילפי.</p>","notation":["ז׳"]},"39952":{"h":"כַּרְזְבָא","r":"KRU09776","alt":["כַּרְזוּבָא"],"source":"krupnik","glosses":[{"text":"a species of locusts","label":""}],"html":"<p>מין ארבה a species of locusts  תרג׳ יב״ע ויק׳ י״א כ״ב (החגב): כרזבא; תה׳ ע״ח מ״ז (חנמל): כרזובא.</p>","notation":[]},"39953":{"h":"כַּרְזַיִים","r":"KRU09778","alt":[],"source":"krupnik","glosses":[{"text":"name of a place in Palestine","label":""}],"html":"<p>בארץ ישראל name of a place in Palestine  מנח׳ פ״ה ע״א: חיטי כרזיים וכפר אחים.</p>","notation":["שם מקום"]},"39954":{"h":"כַּרְזִימִין","r":"KRU09779","alt":[],"source":"krupnik","glosses":[{"text":"dessert","label":""}],"html":"<p>פרפראות לקנוח סעודה dessert  אסת״ר א׳ ט׳: ככרזימין הזה שבא באחרונה.</p>","notation":["ז׳"]},"39955":{"h":"כרח","r":"KRU09780","alt":[],"source":"krupnik","glosses":[{"text":"to force","label":"הִכְרִיחַ הפ׳,"}],"html":"<p>הִכְרִיחַ הפ׳, כפה ואנס to force  שהש״ר ד׳ י״ב: ויעבידו מצרים את בני ישראל אם בעשותן הן מכריחין כל שכן בגופן ובנשותיהם.</p>","notation":["Source marks no qal form"]},"39956":{"h":"כֹּרַח","r":"KRU09781","alt":["עַל כָּרְחִי","בְּעַל כָּרְחִי"],"source":"krupnik","glosses":[{"text":"against or without one’s will","label":""}],"html":"<p>שלא ברצון, על פי אונס against or without one’s will  אבות פ״ד מכ״ג: ועל כרחך אתה חי ועל כרחך אתה מת; סוטה פ״ג מ״ג: ואמרה איני שותה מערערים אותה ומשקים אותה בעל כרחה.</p>","notation":[]},"39957":{"h":"כַּרְטוּסָה","r":"KRU09782","alt":["כַּרְטִיס"],"source":"krupnik","glosses":[{"text":"document","label":""}],"html":"<p>תעודה document  ירוש׳ כת׳ פ״ט ל״ג ע״ג: כהן דמר אבד כרטיסו; שם: לבד מן כרטוסה קדמייא.</p>","notation":[]},"39958":{"h":"כְּרֵי","r":"KRU09783","alt":[],"source":"krupnik","glosses":[{"text":"to dig","label":""}],"html":"<p>חפר to dig  ב״ק נ״א ע״א: זיל כרי לן ואזל כרא להו.</p>","notation":["פ״י"]},"39959":{"h":"כְּרִי","r":"KRU09784","alt":["כַּרְיָא","כַּרְיָה"],"source":"krupnik","glosses":[{"text":"heap, pile","label":""}],"html":"<p>גל, ערימה heap, pile  אהל׳ פט״ו מ״ז: כרי של תבואה או גל של צרורות; ב״מ ק״ה ע״א: ואוקים כריא קדמך; ירוש׳ מעש׳ פ״א מ״ט ע״א: מן דו ישפר אפוי דכריה.</p>","notation":[]},"39960":{"h":"כְּרִיָּה","r":"KRU09785","alt":["כְּרִיּיָה"],"source":"krupnik","glosses":[{"text":"digging","label":""}],"html":"<p>חפירה digging  תוס׳ ב״ק ו׳ י״ג: נפל לפניו מקול הכריה חייב; ב״ק מ״ט ע״ב: שעל עסקי פתיחה ועל עסקי כרייה באה לו.</p>","notation":[]},"39961":{"h":"כָּרִיךְ","r":"KRU09786","alt":[],"source":"krupnik","glosses":[{"text":"moss","label":""}],"html":"<p>ירוקה שעל פני המים, טחב moss  ויק״ר פט״ו: לגנת ירק שהמעיין לתוכה כל זמן שהמעין לתוכה היא עושה כריכין.</p>","notation":["ז׳"]},"39962":{"h":"כְּרִיכָא","r":"KRU09787","alt":[],"source":"krupnik","glosses":[{"text":"winding, rounded","label":"1"},{"text":"strip, ribbon","label":"2"}],"html":"<p>1  winding, rounded  ב״ק נ׳ ע״ב: בור וכו׳ משום דקטין וכריכא וכו׳ אבל מערה דמרבעא וכו׳.\n2  strip, ribbon  סנה׳ ס״ז ע״ב: דנפיץ ושדי כריכי דשיראי מנחיריה.</p>","notation":[]},"39963":{"h":"כְּרִיכָה","r":"KRU09788","alt":[],"source":"krupnik","glosses":[{"text":"bunch","label":"1"},{"text":"scroll","label":"2"},{"text":"winding around","label":"3"}],"html":"<p>1 אגודה bunch  מנח׳ פ״י מ״ג: ועושים אותו כריכות במחובר לקרקע כדי שיהא נוח לקצור.\n2 מגלה scroll  ב״ב י״ג ע״ב: וכתבי הקודש אעפ״י ששניהם רוצים לא יחלוקו וכו׳ לא שנו אלא בכרך אחד אבל בשתי כריכות חולקין.\n3 התפתלות winding around  תנח׳ וארא ד׳: כריכת נחש.</p>","notation":["נ׳"]},"39964":{"h":"כְּרִיכְתָּא","r":"KRU09789","alt":[],"source":"krupnik","glosses":[{"text":"scurf","label":""}],"html":"<p>ארוכה שעל המכה scurf  ב״ק פ״ה ע״א: נאתא כריכתא.</p>","notation":["נ׳"]},"39965":{"h":"כְּרִיסוֹ אַרְגִּירָא","r":"KRU09792","alt":["כְּרִיסוֹאַרְגִּירָא"],"source":"krupnik","glosses":[{"text":"gold and silver tax","label":""}],"html":"<p>מס כסף וזהב gold and silver tax  ירוש׳ ב״ק פ״ג ע״ג: אהן כריסו ארגירא עד לא ייתו כריסוארגירא וכו׳.</p>","notation":[]},"39966":{"h":"כְּרֵיסִית","r":"KRU09793","alt":[],"source":"krupnik","glosses":[{"text":"travelling-bag","label":""}],"html":"<p>מזודה travelling-bag  כל׳ פ״כ מ״א: התורמל וכו׳ הכריסית.</p>","notation":["נ׳"]},"39967":{"h":"כְּרִיסְפָּא","r":"KRU09794","alt":["כְּרִיסְפִּי"],"source":"krupnik","glosses":[{"text":"name of an Amora","label":""}],"html":"<p>שם אמורא name of an Amora  פסי׳ קנ״ז ע״ב: ר׳ כריספא בשם ר׳ יוחנן; ירוש׳ חג׳ פ׳ ע״ו ע״ב: ר׳ כריספי.</p>","notation":[]},"39968":{"h":"כְּרִיָעה","r":"KRU09795","alt":[],"source":"krupnik","glosses":[{"text":"kneeling","label":""}],"html":"<p>נפילה על הכרעים לאות כבוד ולתחינה kneeling  בר׳ ל״ד ע״ב: קידה על אפים וכו׳ כריעה על ברכים.</p>","notation":["נ׳"]},"39969":{"h":"כְּרֵישׁ","r":"KRU09796","alt":["כָּרֵישָׁא","כָּרֵישָׁה"],"source":"krupnik","glosses":[{"text":"porret","label":""}],"html":"<p>מין ירק porret  שבת ע״ט ע״ב – פ׳ ע״א: כדי לזבל בו כרישא; ירוש׳ שם פ״ז ט׳ ע״ד: כדי ליטע כרישה; כלא׳ פ״א מ״ב: כרישין וכרישי שדה.</p>","notation":[]},"39970":{"h":"כְּרִית","r":"KRU09797","alt":[],"source":"krupnik","glosses":[{"text":"groove","label":""}],"html":"<p>חריץ, תעלה groove  ירוש׳ מו״ק פ״א פ׳ ע״ב: פרחה הכרית ולא פסקו וכו׳.</p>","notation":["נ׳"]},"39971":{"h":"כְּרִיתָה","r":"KRU09798","alt":[],"source":"krupnik","glosses":[{"text":"cutting","label":"1"},{"text":"the making of a covenant","label":"2"},{"text":"divorce","label":"4"}],"html":"<p>1 חיתוך וגזירה cutting  יבמ׳ ע״ה ע״ב: מי שע״י כריתה שופך.\n2 ברית כרותה the making of a covenant  מכי׳ משפ׳ כ׳: שלש כריתות שכרת הקב״ה עם ישראל.\n3 עי׳ כָּרֵת. מכות פ״ג מ״ט״ו: כל חייבי כריתות שלקו נפטרו ידי כריתתם. \n4 גירושין, ספר כריתות divorce  גיטי׳ י׳ ע״ב: והא לאו בני כריתה נינהו.</p>","notation":["נ׳"]},"39972":{"h":"כָּרַךְ","r":"KRU09800","alt":[],"source":"krupnik","glosses":[{"text":"to twine around","label":""},{"text":"to embrace","label":""},{"text":"to read without the proper pauses","label":""},{"text":"to be wrapped up","label":""}],"html":"<p>1) חתל to twine around  שבת פי״ט מ״ב: כורך עליה סמרטוט. 2) חיבק to embrace  יומא ל״ח ע״א: עמד הוא וכרכה אמר להם הטילוני עמה. 3) קרא בלי הפסקה to read without the proper pauses  פס׳ פ״ד מ״ח: וכורכין את שמע. נִכְרַךְ נפ׳, נחתל to be wrapped up  ירוש׳ תר׳ פ״ז מ״ו ע״ג: יכרך המת בסדינו. </p>","notation":["פ״י"]},"39973":{"h":"כְּרַךְ","r":"KRU09802","alt":[],"source":"krupnik","glosses":[{"text":"to surround","label":"2"}],"html":"<p>1 עי׳ כָּרַךְ 1. יומא ע״ח ע״ב: כריך סודרא אכרעיה ונפיק. \n2 הקיף to surround  תרג׳ ירמ׳ נ״א נ״ג: וארי תכרוך כרכין תקיפין.</p>","notation":["פ״י"]},"39974":{"h":"כְּרַךְ רִיפְתָּא","r":"KRU09803","alt":[],"source":"krupnik","glosses":[{"text":"to dine","label":""}],"html":"<p>אכל לחם, סעד to dine  בר׳ כ״ב ע״ב: כריכו ריפתא בהדי הדדי.</p>","notation":[]},"39975":{"h":"כָּרֵךְ","r":"KRU09804","alt":[],"source":"krupnik","glosses":[{"text":"to wrap","label":"פיעל, 1"},{"text":"to turn around","label":"פיעל, 2"},{"text":"to be wrapped up","label":"אִכְּרִיךְ אתפ׳, 1"},{"text":"to attach one’s self","label":"אִכְּרִיךְ אתפ׳, 2"}],"html":"<p>פיעל, 1 הליט to wrap  תרג׳ מל״א כ׳ ל״ח (ויתחפש באפר על עיניו): וכריך במעפרא עינוהי.\nפיעל, 2 הסתובב to turn around  תרג׳ מש׳ כ״ו י״ד (תסוב על צירה): דמכרך על צירתיה.\nאִכְּרִיךְ אתפ׳, 1 היה מחותל to be wrapped up  קהל״ר ט׳ י׳: ורישיה מיכרך.\nאִכְּרִיךְ אתפ׳, 2 נטפל ונתחבר to attach one’s self  כת׳ ע״ז ע״ב: מי איכרכת בבעלי ראתן.</p>","notation":[]},"39976":{"h":"כֶּרֶךְ","r":"KRU09805","alt":[],"source":"krupnik","glosses":[{"text":"bundle","label":""},{"text":"scroll","label":""},{"text":"twining","label":""},{"text":"simultaneously","label":""}],"html":"<p>1) צרור, חבילה bundle  תוס׳ מע״ש ד׳ י״א: נתנן כולן בכרך. 2) מגילה scroll  תוס׳ ב״מ ב׳ כ״א: ולא יקראו שלשה בכרך אחד. 3) כריכה וחיתול twining  מנח׳ ל״ט ע״א: חוט של כרך. בְּכֶרֶךְ אֶחָד תה״פ בבת אחת simultaneously  ירוש׳ שקל׳ פ״ג מ״ז ע״ד: מהו לשתותן בכרך אחד וכו׳ אם שתאן בכרך אחד יצא. </p>","notation":["ז׳"]},"39977":{"h":"כְּרָךְ","r":"KRU09806","alt":["כְּרַכָּא"],"source":"krupnik","glosses":[{"text":"city","label":""}],"html":"<p>עיר גדולה city  קד׳ פ״ב מ״ג: בן עיר ונמצא בן כרך בן כרך ונמצא בן עיר; תרג׳ תה׳ ק״ח י״א (מעיר): כרכא רשיעא.</p>","notation":[]},"39978":{"h":"כְּרַכֵּי הַיָּם","r":"KRU09807","alt":[],"source":"krupnik","glosses":[{"text":"sea-towns","label":""}],"html":"<p>ערי חוף הים sea-towns  ספרי במ׳ קט״ו: שמע שיש זונה בכרכי הים והיתה נוטלת ד׳ אמות זהובים בשכרה.</p>","notation":["ז״ר"]},"39979":{"h":"כְּרָכָא","r":"KRU09808","alt":[],"source":"krupnik","glosses":[{"text":"matting","label":""}],"html":"<p>מחצלת matting  שבת י״ט ע״ב: כרכי דזוזי.</p>","notation":["ז׳"]},"39980":{"h":"כִּרְכֵּב","r":"KRU09809","alt":[],"source":"krupnik","glosses":[{"text":"to round off","label":""}],"html":"<p>עיגל, תקן בצורת עיגול to round off  תוס׳ כל׳ ב״מ ב׳ י׳: ואלו הן גולמי כלי מתכות שהן טהורין כל שהוא עתיד לשוף ולגרר ולכרכב וכו׳.</p>","notation":["פ״י"]},"39981":{"h":"כִּרְכָּד","r":"KRU09810","alt":[],"source":"krupnik","glosses":[{"text":"shuttle","label":""}],"html":"<p>יתד הארג shuttle  ירוש׳ שק׳ פ״ד מ״ח ע״ב: שיבטא דכרכד.</p>","notation":["ז׳"]},"39982":{"h":"כַּרְכּוּז","r":"KRU09811","alt":[],"source":"krupnik","glosses":[{"text":"name of a place","label":""}],"html":"<p>name of a place  חול׳ נ״ט ע״ב: עיזא כרכוז. </p>","notation":["שם מקום"]},"39983":{"h":"כַּרְכּוֹם","r":"KRU09812","alt":[],"source":"krupnik","glosses":[{"text":"troop of siege","label":""}],"html":"<p>חיל מצור troop of siege  כתובות כ״ז ע״א: עיר שכבשוה כרכוֹם.</p>","notation":["Marked biblical in source"]},"39984":{"h":"כַּרְכּוֹמָא","r":"KRU09813","alt":[],"source":"krupnik","glosses":[{"text":"works of siege","label":"1"},{"text":"bronze","label":"2"}],"html":"<p>1 סוללה works of siege  תרג׳ דב׳ כ׳ כ׳ (מצור) : כרכומא.\n2 נחושת bronze  תרג׳ איוב כ׳ כ״ד (קשת נחושה): קשתא דכרכומא.</p>","notation":["ז׳"]},"39985":{"h":"כַּרְכּוּשְׁתָּא","r":"KRU09816","alt":[],"source":"krupnik","glosses":[{"text":"weasel","label":""}],"html":"<p>חולדה weasel  סנה׳ ק״ה ע״ב: כרכושתא ושונרא.</p>","notation":["נ׳"]},"39986":{"h":"כּרְכֵּם","r":"KRU09818","alt":[],"source":"krupnik","glosses":[{"text":"to paint, to varnish","label":""},{"text":"to change colours","label":""}],"html":"<p>צבע to paint, to varnish  כל׳ פט״ו מ״ב: סרקן או כרכמן. נִתְכַּרְכֵּם נתפ׳, נעשה מגוון to change colours  ב״ר פ״כ: ולא יכול להשיבו ונתכרכמו פניו. </p>","notation":["פ״י"]},"39987":{"h":"כַּרְכְּמִישָׁא","r":"KRU09819","alt":[],"source":"krupnik","glosses":[{"text":"lead","label":""}],"html":"<p>עופרת lead  תרג׳ איוב י״ט כ״ד (בעט ברזל ועופרת): בקולמוס דפרזלא וכרכמישא.</p>","notation":["ז׳"]},"39988":{"h":"כַּרְכְּמִית","r":"KRU09820","alt":[],"source":"krupnik","glosses":[{"text":"a woman’s name","label":""}],"html":"<p>שם אשה a woman’s name  עדיות פ״ה מ״ו: מעשה בכרכמית שפחה משוחררת שהיתה בירושלים.</p>","notation":[]},"39989":{"h":"כִּרְכְּרָן","r":"KRU09823","alt":[],"source":"krupnik","glosses":[{"text":"dances","label":""}],"html":"<p>מחולות dances  תרג׳ יש׳ ס״ו כ׳ (בכרכרות): בכרכרן ובתושבחן.</p>","notation":["ז״ר"]},"39990":{"h":"כַּרְכֵּשׁ","r":"KRU09824","alt":[],"source":"krupnik","glosses":[{"text":"to nod","label":""}],"html":"<p>הניע to nod  נדה מ״ב ע״ב: כרכיש ליה ברישיה.</p>","notation":["פ״י"]},"39991":{"h":"כַּרְכְּשָׁא","r":"KRU09825","alt":[],"source":"krupnik","glosses":[{"text":"rectum","label":""}],"html":"<p>מֵעה התחתון, פי הטבעת rectum  בר׳ ס״ב ע״ב: שמטיה לכרכשיה.</p>","notation":["ז׳"]},"39992":{"h":"כַּרְכַּשְׁתָּא","r":"KRU09826","alt":[],"source":"krupnik","glosses":[{"text":"fringes","label":"2"}],"html":"<p>1 כנ״ל. שבת פ״ב ע״א: דהאי כרכשתא אתלת שיני יתיב. \n2 גדילים fringes  ב״מ ז׳ ע״א: דתפיסי בכרכשתא.</p>","notation":["נ׳"]},"39993":{"h":"כְּרַכְתָּא","r":"KRU09827","alt":[],"source":"krupnik","glosses":[{"text":"a fenced in plantation","label":""}],"html":"<p>שדה גדור a fenced in plantation  ב״מ כ״ב ע״ב: כרכתא מאי.</p>","notation":["נ׳"]},"39994":{"h":"כָּרַם","r":"KRU09828","alt":[],"source":"krupnik","glosses":[{"text":"to pile up","label":""}],"html":"<p>גיבב וגדש to pile up  כל׳ פכ״ג מ״ה: וכסא של כובס שהוא כורם עליו את הכלים.</p>","notation":["Marked biblical in source"]},"39995":{"h":"כֶּרֶם","r":"KRU09829","alt":[],"source":"krupnik","glosses":[{"text":"the academy of Jabne","label":""}],"html":"<p>כֶּרֶם בְּיַבְנֶה בית מדרש התנאים ביבנה the academy of Jabne  ירוש׳ בד׳ פ״ד ז׳ ע״ד: דרש ר׳ אלעזר בן עזריה לפני חכמים בכרם ביבנה וכי כרם היה שם אלא אילו תלמידי חכמים שהיו עשויין שורות שורות ככרם.</p>","notation":["Marked biblical in source"]},"39996":{"h":"כֶּרֶם רְבָעִי","r":"KRU09830","alt":[],"source":"krupnik","glosses":[{"text":"a vineyard of the fourth year’s crop (after the three years of Orlah)","label":""}],"html":"<p>כרם בשנתו הרביעית (לאחר שלש שנות ערלה) a vineyard of the fourth year’s crop (after the three years of Orlah)  מעש״ש פ״ה מ״א: כרם רבעי מציינין אותו בקוזזות אדמה ושל ערלה בחרסית.</p>","notation":[]},"39997":{"h":"כַּרְמוֹן","r":"KRU09831","alt":[],"source":"krupnik","glosses":[{"text":"a row of vines","label":""}],"html":"<p>שורת גפנים a row of vines  ירוש׳ כלא׳ פ״ד כ״ט ע״א: נסב חד כרמון.</p>","notation":["ז׳"]},"39998":{"h":"כַּרְמִי","r":"KRU09832","alt":[],"source":"krupnik","glosses":[{"text":"name of a place in Babylonia","label":""}],"html":"<p>בבבל name of a place in Babylonia  יבמ׳ קכ״א ע״א: דאטבע בכרמי ואסקי אבי חוורי. </p>","notation":["שם מקום"]},"39999":{"h":"כַּרְמְלִית","r":"KRU09833","alt":[],"source":"krupnik","glosses":[{"text":"an area which cannot be classified either as private ground or as public ground","label":""}],"html":"<p>מקום שאינו לא רשות היחיד ולא רשות הרבים an area which cannot be classified either as private ground or as public ground  ירוש׳ שבת פ״א ב׳ ע״ד: הזורק בכל הים פטור שכל הים נקרא כרמלית.</p>","notation":["נ׳"]},"40000":{"h":"כָּרֶמֶת","r":"KRU09834","alt":[],"source":"krupnik","glosses":[{"text":"vines trained over the wall of the vineyard","label":""}],"html":"<p>גפן מודלה על גדר הכרם vines trained over the wall of the vineyard  תוס׳ מנח׳ ט׳ י׳: אין מביאין לא מן הכרמת וכו׳ אלא מן הדליות המיוחדות לכך.</p>","notation":["נ׳"]},"40001":{"h":"כְּרַן","r":"KRU09835","alt":[],"source":"krupnik","glosses":[{"text":"the very day","label":""}],"html":"<p>עצם היום the very day  תרג׳ בר׳ ז׳ י״ג (בעצם היום הזה): בכרן יומא הדין.</p>","notation":["Used in: כְּרַן יוֹמָא"]},"40002":{"h":"כַּרְנְבוֹ","r":"KRU09836","alt":[],"source":"krupnik","glosses":[{"text":"a woman's name","label":""}],"html":"<p>שם אשה a woman&#x27;s name  ב״ב צ״א ע״א: אמיה דאברהם אמתלאי בת כרנבו.</p>","notation":[]},"40003":{"h":"כרנבי","r":"KRU09837","alt":[],"source":"krupnik","glosses":[{"text":"chicory","label":""}],"html":"<p>מין צמח chicory  איכ״ר ג׳ מ״ב: כרנבי מרירן.</p>","notation":["ז׳","Source emendation: אִנְדִּבִי"]},"40004":{"h":"כֶּרֶס","r":"KRU09838","alt":[],"source":"krupnik","glosses":[{"text":"belly","label":""}],"html":"<p>בטן, כרש belly  תענ׳ כ״ו ע״א: נפש שבעה וכרס מליאה.</p>","notation":["נ׳"]},"40005":{"h":"כַּרְסָא","r":"KRU09839","alt":[],"source":"krupnik","glosses":[{"text":"issue of the womb","label":"2"},{"text":"the interior","label":"3"}],"html":"<p>1 כנ״ל. חול׳ נ״ו ע״ב: פקעא כרסיה ונפוק מעייניה. \n2 פרי בטן issue of the womb  יבמ׳ ס״ה ע״ב: אילו ילדת לי הדא כרסא אחריתי.\n3 פנימיות the interior  ב״ר פס״ח: בכרסא דביתך.</p>","notation":[]},"40006":{"h":"כַּרְסָנָא","r":"KRU09841","alt":[],"source":"krupnik","glosses":[{"text":"a man’s name","label":""}],"html":"<p>a man’s name  ירוש׳ דמאי פ״ג סה״א: ר׳ שמעון בנכרסנא. </p>","notation":["שם איש"]},"40007":{"h":"כַּרְסֶפֶת","r":"KRU09842","alt":[],"source":"krupnik","glosses":[{"text":"a species of locusts","label":""}],"html":"<p>מין ארבה a species of locusts  חול׳ ס״ה ע״ב: למינהו להביא את הכרספת.</p>","notation":["נ׳"]},"40008":{"h":"כַּרְסָתָן","r":"KRU09843","alt":[],"source":"krupnik","glosses":[{"text":"large-bellied","label":""}],"html":"<p>בעל כרס גדולה large-bellied  חול׳ ס׳ ע״א: שור פרסתן וכרסתן.</p>","notation":["ת׳"]},"40009":{"h":"כָּרַע","r":"KRU09844","alt":[],"source":"krupnik","glosses":[{"text":"to overbalance, to outweigh","label":""},{"text":"to decide","label":""},{"text":"to harmonize","label":""}],"html":"<p>עי׳ הִכְרִיעַ 1. זבים פ״ד מ״ה: בכף מאזנים ומשכב ומושב כנגדו כרע הזב וכו׳. הִכְרִיעַ·– הפ׳ 1) הטה לצד אחד, ביחוד במשקל to overbalance, to outweigh  אבות פ״ב מי״ב: אם יהיו חכמי ישראל בכף מאזנים ואליעזר בן הורקנוס בכף שניה מכריע את כולם. 2) החליט וגזר to decide  תוס׳ פס׳ ב׳ ז׳: הדבר עדיין שקול מי מכריע אמר לו ר׳ יהושע אני אכריע. 3) התאים וישב סתירה to harmonize  ירוש׳ סוטה פ״א י״ז ע״א: מקרא אחד מכריע שני מקראות. </p>","notation":["Marked biblical in source"]},"40010":{"h":"כְּרַע","r":"KRU09845","alt":[],"source":"krupnik","glosses":[{"text":"to bow","label":""},{"text":"to sadden","label":""},{"text":"to weigh","label":""},{"text":"to be weighed","label":""}],"html":"<p>1) נטה to bow  ירוש׳ בר׳ פ״ב ה׳ ע״א: כרע מגרמיה. 2) עי׳ הִכְרִיַע 2. תרג׳ יב״ע דב׳ כ״ה א׳ (והצדיקו): ויכעון לזכותא. אַכְרַע  אפ׳, 1) העכיר to sadden  תרג׳ שופ׳ י״א ל״ה (הכרע הכרעתני): אכרעא אכרעתיני. 2) שקל to weigh  פסיק׳ בשלח פפ״ב: באכרעתא דאכרעון וכו׳. אִתְכְּרַע אתפ׳, נשקל to be weighed  שם: באכרעתא דאכרעון וכו׳ אתכרע. </p>","notation":["פ״י"]},"40011":{"h":"כֶּרַע","r":"KRU09846","alt":[],"source":"krupnik","glosses":[{"text":"leg of a piece of furniture","label":""}],"html":"<p>רגל של כלי leg of a piece of furniture  תוס׳ ב״ק ח׳ י״ג: לקח לו עז וקשרה בכרעי המטה.</p>","notation":["Marked biblical in source"]},"40012":{"h":"כַּרְעָא","r":"KRU09847","alt":[],"source":"krupnik","glosses":[{"text":"leg","label":""}],"html":"<p>רגל leg  יומא י״א ע״ב: כי עקר אינש כרעיה דימינא עקר ברישא.</p>","notation":["ז׳"]},"40013":{"h":"כרף","r":"KRU09848","alt":[],"source":"krupnik","glosses":[{"text":"to develop","label":"אִיכְּרַף אתפ׳,"}],"html":"<p>אִיכְּרַף אתפ׳, גדל ונתפתח to develop  נדה מ״ח ע״ד: איכרפו דדיך.</p>","notation":["Source marks no qal form"]},"40014":{"h":"כַּרְפּוּזְנָה","r":"KRU09849","alt":[],"source":"krupnik","glosses":[{"text":"a kind of beans","label":""}],"html":"<p>מין פולין a kind of beans  ירוש׳ כלא׳ פ״א כ״ז ע״א: פול הלבן – כרפוזנה.</p>","notation":["נ׳"]},"40015":{"h":"כַּרְפַּס","r":"KRU09850","alt":[],"source":"krupnik","glosses":[{"text":"celery","label":""}],"html":"<p>מין ירק celery  שבי׳ פ״ט מ״א : כוסבר שבהרים והכרפס שבנהרות. </p>","notation":["Marked biblical in source"]},"40016":{"h":"כַּרְפְּסָא","r":"KRU09851","alt":[],"source":"krupnik","glosses":[{"text":"a kind of flax","label":"2"}],"html":"<p>1 כנ״ל. כת׳ ס״א ע״א: דאכלה כרפסא הוו לה בני זיותני. \n2 מין פשתן a kind of flax  ע״ז ל״ח ע״ב: ביזרא דכרפסא.</p>","notation":["ז׳"]},"40017":{"h":"כַּרְקוֹם","r":"KRU09853","alt":[],"source":"krupnik","glosses":[{"text":"pole","label":"1"},{"text":"works of siege","label":"2"},{"text":"troop of siege","label":"3"}],"html":"<p>1 מוט pole  ב״ר פצ״ח: גפן שכחה רע אוסרין לה כרקום אחד.\n2 סוללה works of siege  גיט׳ כ״ח ע״ב: עיר שהקיפה כרקום.\n3 חיל מצור troop of siege  תוס׳ ע״ז ב׳ ו׳: ההולך לאיצטרטיונין ולכרקומין.</p>","notation":["ז׳"]},"40018":{"h":"כָּרֵשָׁא","r":"KRU09854","alt":[],"source":"krupnik","glosses":[{"text":"a fish","label":""}],"html":"<p>מין דג a fish  ב״ב ע״ד ע״א: מיני דכוורי דמקרי כרשא.</p>","notation":["ז׳"]},"40019":{"h":"כָּרְשִׁינָא","r":"KRU09855","alt":[],"source":"krupnik","glosses":[{"text":"pebble","label":""}],"html":"<p>גוש אדמה pebble  שבת פ״א ע״ב: כרשיני בבלייתא.</p>","notation":["נ׳"]},"40020":{"h":"כַּרְשִׁינָה","r":"KRU09856","alt":[],"source":"krupnik","glosses":[{"text":"ervum (bot.)","label":"1"},{"text":"an alkaline plant","label":"2"}],"html":"<p>1 מין צמח המשמש למאכל בהמה ervum (bot.)  מעש״ש פ״ב מ״ב: בכרשינים ובתלתן.\n2 מין צמח המשמש לבורית an alkaline plant  כרית׳ ו׳ ע״א: בורית כרשינה.</p>","notation":["נ׳"]},"40021":{"h":"כָּרַת","r":"KRU09858","alt":[],"source":"krupnik","glosses":[{"text":"to decree excision","label":""},{"text":"to separate, to divorce","label":""},{"text":"to decide","label":""},{"text":"to mutilate","label":""},{"text":"to be mutilated","label":""},{"text":"to be covenanted","label":""}],"html":"<p>1) ענש בעונש כרת to decree excision  ירוש׳ סנה׳ פי״א ל׳ ע״ב: צא מהן עשרים שנה שאין בית דין של מעלה עונשין וכורתים. 2) הפריד to separate, to divorce  גיט׳ כ״א ע״ב: דבר הכורת בינו לבינה. 3) גזר והחליט to decide  בר׳ ד׳ ע״א: כרתי וכו׳ שכורתים דבריהם. 4) סירס to mutilate  בכור׳ ל״ג ע״ב: נותק אחר כורת. נִכְרַת·– נפ׳ 1) נסתרס to be mutilated  יבמ׳ פ״ח מ״ב: שנכרת הגיד. 2) הותנה to be covenanted  תוס׳ סוטה ח׳ י״א: ואין לך כל דבר ודבר שלא נכרתו עליו ארבעים ושמונה בריתות. </p>","notation":["Marked biblical in source"]},"40022":{"h":"כֵּרֵת","r":"KRU09859","alt":[],"source":"krupnik","glosses":[{"text":"to doom to „Kareth“","label":"פיעל,"}],"html":"<p>פיעל, גזר עליו עונש כרת to doom to „Kareth“  ערכ׳ ט״ו ע״ב: אין לו תקנה שכבר כרתו דוד.</p>","notation":[]},"40023":{"h":"כָּרֵת","r":"KRU09860","alt":[],"source":"krupnik","glosses":[{"text":"divine punishment through premature or sudden death","label":""}],"html":"<p>מיתה בידי שמים לעונש על חטאים קשים divine punishment through premature or sudden death  מו״ק כ״ח ע״א: מת בחמשים שנה זו היא מיתת כרת.</p>","notation":["ז׳"]},"40024":{"h":"כַּרְתִּי","r":"KRU09861","alt":[],"source":"krupnik","glosses":[{"text":"leek","label":""}],"html":"<p>מין ירק leek  בר׳ פ״א מ״ב: משיכיר וכו׳ בין תכלת לכרתי.</p>","notation":["ז׳"]},"40025":{"h":"כְּרֵתִינוֹן","r":"KRU09862","alt":[],"source":"krupnik","glosses":[{"text":"leek-coloured, green","label":""}],"html":"<p>מצבע הכרתי, ירוק leek-coloured, green  ירוש׳ סוכה פ״ג נ״ג ע״ד: כהן כרתינון או דדמי להן כרתינון.</p>","notation":["ת׳"]},"40026":{"h":"כְּרַתְנִין","r":"KRU09864","alt":[],"source":"krupnik","glosses":[{"text":"green material","label":""}],"html":"<p>ארג ירוק green material  תרג׳ אס׳ א׳ ו׳ (כרפס): כרתנין.</p>","notation":["ז״ר"]},"40027":{"h":"כַּשְׂדָּאָה","r":"KRU09868","alt":[],"source":"krupnik","glosses":[{"text":"Chaldean","label":""}],"html":"<p>כשדי Chaldean  תרג׳ יר׳ כ״ה י״ב (ארץ כשדים): ארע כשדאי.</p>","notation":["ת׳"]},"40028":{"h":"כִּשּׁוּף","r":"KRU09869","alt":[],"source":"krupnik","glosses":[{"text":"sorcery","label":""}],"html":"<p>קסמים sorcery  פסיק״ר י״ד: לא כשוף ולא כשפים עשיתי.</p>","notation":["ז׳"]},"40029":{"h":"כָּשׁוֹרָא","r":"KRU09870","alt":[],"source":"krupnik","glosses":[{"text":"beam","label":""}],"html":"<p>קורה beam  ב״ק ס״ו ע״ב: והוי מריש דאיכא שינוי השם דמעיקרא כשורא והשתא מללא.</p>","notation":["ז׳"]},"40030":{"h":"כְּשׁוּת","r":"KRU09871","alt":[],"source":"krupnik","glosses":[{"text":"cuscuta","label":"1"},{"text":"down","label":"2"}],"html":"<p>1 מין צמח cuscuta  כלא׳ א׳ י״א: ואין מרכיבין כשות ע״ג האיזמא.\n2 שערות דקות ורכות down  מהוא׳ פ״ט מ״ד: כשות של קטן.</p>","notation":["נ׳"]},"40031":{"h":"כשט","r":"KRU09873","alt":[],"source":"krupnik","glosses":[{"text":"to prosper","label":"אַכְשַׁט אפ׳,"}],"html":"<p>אַכְשַׁט אפ׳, הצליח to prosper  תרג׳ יה׳ א׳ ח׳ (תשכיל): תכשט.</p>","notation":["Source marks no qal form"]},"40032":{"h":"כַּשִּׁירָא","r":"KRU09874","alt":[],"source":"krupnik","glosses":[{"text":"industrious","label":""}],"html":"<p>חרוץ industrious  תרג׳ מש׳ י׳ ד׳ (ויד חרוצים תעשיר): ידיו דכשירין מעתרא להון.</p>","notation":["ת׳"]},"40033":{"h":"כְּשֵׁירוּת","r":"KRU09875","alt":[],"source":"krupnik","glosses":[{"text":"ability","label":""}],"html":"<p>חריצות ability  קהל״ר ג׳ ט׳: מה מהני אומנא באימנותיה וכשירא בכשירותיה.</p>","notation":["נ׳"]},"40034":{"h":"כִּשְׁכּוּשׁ","r":"KRU09876","alt":[],"source":"krupnik","glosses":[{"text":"wag (the tail)","label":""}],"html":"<p>הנעה בזנב wag (the tail)  ב״ק י״ט ע״ב: כשכוש יתירא.</p>","notation":["ז׳"]},"40035":{"h":"כִּשְׁכֵּשׁ","r":"KRU09877","alt":[],"source":"krupnik","glosses":[{"text":"to shake, to wag (the tail etc.)","label":"1"},{"text":"to pat","label":"2"}],"html":"<p>1 הניע בזנב וכדומה to shake, to wag (the tail etc.)  חול׳ פ״ב מ״ו :עד שתכשכש בזנבה; שם ל״ח ע״א: וכשכשה באזנה.\n2 החליק to pat  פסידר״כ זכור: הסוס הזה את ממתגו וכו׳ מכשכשו והוא בולם.</p>","notation":["פ״י"]},"40036":{"h":"כָּשָׁף","r":"KRU09878","alt":[],"source":"krupnik","glosses":[{"text":"a resiniferous tree","label":""}],"html":"<p>מין עץ הנוטף שרף a resiniferous tree  שבת כ״ג ע״א: כל השרפין יפין לדיו ושרף כשף יפה מכולם.</p>","notation":["ז׳"]},"40037":{"h":"כַּשְׁפָּן","r":"KRU09879","alt":[],"source":"krupnik","glosses":[{"text":"sorcerer","label":""}],"html":"<p>עושה מעשי כשפים sorcerer  מדר׳ תה׳ בובר פ׳: כשפנין ונואפין ורצחנין.</p>","notation":["ת׳"]},"40038":{"h":"כָּשֵׁר","r":"KRU09880","alt":[],"source":"krupnik","glosses":[{"text":"to be proper, to be fit","label":""},{"text":"to prepare","label":""},{"text":"to permit","label":""},{"text":"to make an object fit for levitical uncleanness","label":""},{"text":"to work with zeal","label":""},{"text":"to be fit","label":""}],"html":"<p>היה ראוי ונכון עפ״י דין to be proper, to be fit  ספרי במ׳ קמ״ח: במנחות הבאות קודם לעומר שלא כשרו לא לגבוה ולא להדיוט. הִכְשִׁיר הפ׳ 1) אפשר, גרם to prepare  ב״ק פ״א מ״ב: כל שחבתי בשמירתו הכשרתי את נזקו. 2) התיר to permit  סוכה פ״ב מ״ז: בית שמאי פוסלין ובית הלל מכשירין. 3) סיגל לקבל טומאה to make an object fit for levitical uncleanness  חול׳ ל״ה ע״ב: וכי הדם מכשיר. הִתְכַּשֵּׁר התפ׳, 1) הזדרז, היה שוקד to work with zeal  קה״ר ה׳ י״א: מתכשר במלאכתו. 2) היה כשר to be fit  מנח׳ י׳ ע״ב: סד״א וכו׳ תתכשר. </p>","notation":["פ״ע","Marked biblical in source"]},"40039":{"h":"כְּשַׁר","r":"KRU09881","alt":[],"source":"krupnik","glosses":[{"text":"to grow better","label":""},{"text":"to be fit, to be made fit","label":""}],"html":"<p>עי׳ כָּשֵׁר 1. תרג׳ ויק׳ ד׳ ב׳ (אשר לא תעשינה): דלא כשרין לאתעבדא. אַכְשַׁר  אפ׳, 1) עי׳ הִכְשִׁיר 1. ב״מ פ״ט ע״ב: לאכשורי גברא וכו׳ לאכשורי פירא. 2) הוטב to grow better  יבמ׳ ל״ט ע״ב: אכשור דרא. אִתְכְּשַׁר, אִיכְּשַׁר אתפ׳, הוכשר to be fit, to be made fit  חול׳ ל״ו ע״ב: איתכשר במשקי; תרג׳ יכ״ע ויק׳ י״א מ״ז (ובין החיה הנאכלת ובין החיה אשר לא תאכל): ביני חייתא דמיכשרא לאיתאכלא וביני חייתא דלא מיכשרא לאיתאכלא. </p>","notation":[]},"40040":{"h":"כָּשֵׁר²","r":"KRU09882","alt":[],"source":"krupnik","glosses":[{"text":"fit","label":"1"},{"text":"ritually permitted","label":"2"},{"text":"kosher","label":"3"},{"text":"honest","label":"4"}],"html":"<p>1 מסוגל fit  שבת פ״ז מ״ג: כל הכשר להצניע וכו׳ וכל שאינו כשר להצניע.\n2 מותר ritually permitted  קיד׳ פ״ד מ״ו: בתו כשרה לכהונה.\n3 ראוי לאכילה מצד הדין kosher  חול׳ פ״ג מ״ב: אלו כשרות בבהמה.\n4 ישר honest  בר׳ פ״ב מ״ז: אין טבי עבדי כשאר כל העבדים כשר היה.</p>","notation":["ת׳"]},"40041":{"h":"כַּשָּׁר","r":"KRU09883","alt":[],"source":"krupnik","glosses":[{"text":"vindicating witness","label":""}],"html":"<p>עֵד כשרות vindicating witness  כת׳ מ״ו ע״א: מאי לא מצאתי לבתך בתולים לא מצאתי לבתך כשרי בתולים.</p>","notation":["ז׳"]},"40042":{"h":"כַּשְׁרוּת","r":"KRU09884","alt":[],"source":"krupnik","glosses":[{"text":"legitimacy","label":"1"},{"text":"honesty","label":"2"},{"text":"ability","label":"3"},{"text":"fitness","label":"4"}],"html":"<p>1 היתר legitimacy  קיד׳ ע״ב ע״ב: כל ארצות בחזקת כשרות הן עומדות.\n2 יושר honesty  במ״ר פ״ב: שבתחלה הבריות נוהגות בכשרות.\n3 חריצות ability  קה״ר ה׳ י״א: יגע זה וכו׳ בכשרות מה שלא יגעתם אתם כל היום.\n4 סגולה, כשרון, יכולת fitness  יב׳ פ׳ ע״א: כל שלא ראה שעה אחת בכשרותו.</p>","notation":["נ׳"]},"40043":{"h":"כָּשַׁרְתָּא","r":"KRU09885","alt":[],"source":"krupnik","glosses":[{"text":"pachac","label":""}],"html":"<p>מין שיח pachac  בר׳ מ״ג ע״א: האי כשרתא מברכין עלויה בורא עצי בשמים.</p>","notation":["נ׳"]},"40044":{"h":"כַּת","r":"KRU09889","alt":[],"source":"krupnik","glosses":[{"text":"party","label":""}],"html":"<p>חבורה party  ירוש׳ נדר׳ פ״ו מ׳ ע״א: חביבה עלי כת קטנה שבארץ ישראל מסנהדרין גדולה שבחו״ל.</p>","notation":["נ׳"]},"40045":{"h":"כַּתָּא","r":"KRU09890","alt":[],"source":"krupnik","glosses":[{"text":"after-crop","label":""}],"html":"<p>ספיח after-crop  תרג׳ ויק׳ כ״ה ה׳ (ספיח קצירך): כתא דחצדך.</p>","notation":["ז׳"]},"40046":{"h":"כָּתַב","r":"KRU09891","alt":[],"source":"krupnik","glosses":[{"text":"to assign, to will","label":""},{"text":"to cause to be written","label":""},{"text":"to enlist in the army","label":""}],"html":"<p>מסר את נכסיו לפלוני בצוואה to assign, to will  ב״ב פ״ט מ״ו: שכיב מרע שכתב כל נכסיו לאחרים. הִכְתִּיב הפ׳, 1) גרם לכתוב to cause to be written  מכי׳ יתרו ז׳: כביכול הכתיב על עצמו שברא את עולמו בששה ימים ונח בשביעי. 2) קרא לצבא to enlist in the army  ב״ר פמ״ב: זו מלכות אדום שהיא מכתבת טירוניא מכל אומות העולם. </p>","notation":["Marked biblical in source"]},"40047":{"h":"כְּתַב","r":"KRU09892","alt":[],"source":"krupnik","glosses":[{"text":"to write","label":""},{"text":"to be written, to be recorded","label":""}],"html":"<p>כתב ורשם to write  נד׳ ל״ז ע״ב: קריין ולא כתיבן כתיבן ולא קריין הלכה למשה מסיני. אִתְכְּתִיב, אִיכְּתִיב אתפ׳, נכתב ונרשם to be written, to be recorded  תרג׳ אס׳ ח׳ ח׳: פתקא דמתכתיב; מגי׳ ז׳ ע״א: דאיבעי איכתיב ודלא איבעי לא איכתיב. </p>","notation":["פ״י"]},"40048":{"h":"כְּתָב כְּתַב יָד","r":"KRU09893","alt":[],"source":"krupnik","glosses":[{"text":"signature, hand","label":""},{"text":"in writing","label":""}],"html":"<p>צורת הכתיבה של איש ואיש, חתימה signature, hand  כת׳ פ״ב מ״י: ואלו נאמנין להעיד וכו׳ זה כתב ידו של אבא וזה כתב ידו של רבי וזה כתב ידו של אחי. בִּכְתָב תה״פ לא בעל פה in writing  תמורה י״ד ע״ב: דברים שעל פה אי אתה רשאי לאומרן בכתב ושבכתב אי אתה רשאי לאומרן על פה. </p>","notation":["Marked biblical in source"]},"40049":{"h":"כַּתְבָה","r":"KRU09894","alt":[],"source":"krupnik","glosses":[{"text":"a man’s name","label":""}],"html":"<p>a man’s name  במ״ר פי״ד: סומה בר כתבה. </p>","notation":["שם איש"]},"40050":{"h":"כַּתְבָן","r":"KRU09895","alt":[],"source":"krupnik","glosses":[{"text":"writer","label":""}],"html":"<p>כותב, סופר writer  קהל״ר ב׳ י״ח: ר׳ מאיר היה כתבן טב מובחר.</p>","notation":["ז׳"]},"40051":{"h":"כָּתוּב","r":"KRU09896","alt":[],"source":"krupnik","glosses":[{"text":"the Bible text","label":"1"},{"text":"Biblical verse","label":"2"}],"html":"<p>1 מקרא, גוף המקרא the Bible text  חג׳ י״ח ע״א: במה הכתוב מדבר וכו׳.\n2 פסוק במקרא Biblical verse  מכי׳ יתרו ט׳: כתוב אחד אומר וכו׳ וכתוב אחד אומר וכו׳ כיצד יתקיימו שני המקראות הללו.</p>","notation":["ז׳"]},"40052":{"h":"כְּתוּבִים","r":"KRU09897","alt":[],"source":"krupnik","glosses":[{"text":"the third and last part of the Bible, Hagiographa","label":""}],"html":"<p>החלק השלישי והאחרון בכתבי הקודש the third and last part of the Bible, Hagiographa  מג׳ ל״א ע״א: כתוב בתורה ושנוי בנביאים ומשולש בכתובים.</p>","notation":["ז״ר"]},"40053":{"h":"כָּתוֹבָא","r":"KRU09899","alt":["כָּתוֹבָה"],"source":"krupnik","glosses":[{"text":"writer","label":""}],"html":"<p>סופר, לבלר writer  ירוש׳ סנה׳ פ״ב י״ט ע״ד: ר׳ חנינא כתובא (הור׳ פ״ג מ״ז ע״א: כתובה).</p>","notation":[]},"40054":{"h":"כְּתוּבָּה","r":"KRU09900","alt":[],"source":"krupnik","glosses":[{"text":"marriage contract","label":"1"},{"text":"deed","label":"2"}],"html":"<p>1 שטר נשואין marriage contract  בת׳ ס״ו ע״ב: זכור אני כשחתמתי על כתובתה של זו והייתי קורא בה אלף אלפים דינרי זהב מבית אביה חוץ משל חמיה.\n2 שטר בכלל deed  כת׳ נ״ב ע״ב – נ״ג ע״א: כתובת בנין דכרין.</p>","notation":["נ׳"]},"40055":{"h":"כְּתוּשָׁא","r":"KRU09904","alt":[],"source":"krupnik","glosses":[{"text":"scab, wound","label":""}],"html":"<p>חבורה, פצע scab, wound  ב״מ ל״ח ע״א: דבש לכתושא דגמלא.</p>","notation":["ז׳"]},"40056":{"h":"כְּתִיב","r":"KRU09905","alt":[],"source":"krupnik","glosses":[{"text":"the traditional spelling of some Biblical words, opp. to the Massoretic instruction for reading","label":""}],"html":"<p>צורת המלה כמו שהיא כתובה במקרא, בנגוד לקרי שעפ״י המסורה, קרי the traditional spelling of some Biblical words, opp. to the Massoretic instruction for reading  סנה׳ כ׳ ע״א: כתיב להכרות וקרינן להברות.</p>","notation":["ז׳"]},"40057":{"h":"כְּתִיבָה","r":"KRU09906","alt":[],"source":"krupnik","glosses":[{"text":"writing","label":"1"},{"text":"the word in the Sh’ma’ recitation","label":"2"},{"text":"i>Wort","label":"2"}],"html":"<p>1 פעולת הכותב writing  שבת ק״ג ע״ב: שתהא כתיבה תמה שלא יכתוב אלפין עיינין.\n2 המלה “וכתבתם„ בקריאת שמע the word in the Sh’ma’ recitation  וכתבתם וכתבתם &lt;i&gt;Wort בר׳ ט״ז ע״א: בין כתיבה לכתיבה יחזור לכתיבה ראשונה.</p>","notation":["נ׳"]},"40058":{"h":"כָּתִים","r":"KRU09907","alt":[],"source":"krupnik","glosses":[{"text":"red","label":""}],"html":"<p>ארום red  תרג׳ יש׳ א׳ י״ח (כשנים): כתימין כצבעונין.</p>","notation":["ת׳"]},"40059":{"h":"כתיף","r":"KRU09908","alt":[],"source":"krupnik","glosses":[{"text":"girder","label":""}],"html":"<p>קורה girder  תוס׳ צוק׳ כל׳ ב״ב ב׳ ג׳: שני כתיפין היו בבית אבא וכו׳ זה שהוא חקוק טמא וזה שאין חקוק טהור ועליו ישב חגי הנביא.</p>","notation":["ז׳","Source emendation: כָּפִיס"]},"40060":{"h":"כְּתִישָׁה","r":"KRU09909","alt":[],"source":"krupnik","glosses":[{"text":"pounding","label":""}],"html":"<p>כתיתה ודיכה pounding  שהש״ר א׳ ג׳: השמן הזה אין משתבח אלא ע״י כתישה.</p>","notation":["ז׳"]},"40061":{"h":"כָּתִית","r":"KRU09910","alt":[],"source":"krupnik","glosses":[{"text":"scab","label":"1"},{"text":"tatters","label":"2"},{"text":"pounded wheat","label":"3"}],"html":"<p>1 חבורה scab  שבת פ״ח מ״א: דבש כדי ליתן על הכתית.\n2 סמרטוט tatters  תוס׳ שבת י״ב י״ד: לא גמי יבש ולא כתיתין יבשין.\n3 חטים כתותים pounded wheat  מדר׳ תה׳ ט״ו: מיני כתיתין וכו׳ מי יוכל לשבוע מאלו.</p>","notation":["ז׳","Marked biblical in source"]},"40062":{"h":"כָּתְלָא","r":"KRU09912","alt":[],"source":"krupnik","glosses":[{"text":"wall","label":""}],"html":"<p>קיר, כותל wall  תרג׳ מל״ב ד׳ י׳ (עלית קיר): עלית כתלא.</p>","notation":["ז׳"]},"40063":{"h":"כָּתְלֵי דַחֲזִירֵי","r":"KRU09913","alt":[],"source":"krupnik","glosses":[{"text":"bacon","label":""}],"html":"<p>שומן חזיר bacon  חול׳ י״ז ע״א: כתלי דחזירי.</p>","notation":[]},"40064":{"h":"כֶּתֶם","r":"KRU09914","alt":[],"source":"krupnik","glosses":[{"text":"stain","label":""}],"html":"<p>לכלוך, רבב stain  שבת פ״ט מ״ה: נתר ובורית וכו׳ כדי להעביר על הכתם.</p>","notation":["Marked biblical in source"]},"40065":{"h":"כַּתָּן","r":"KRU09915","alt":[],"source":"krupnik","glosses":[{"text":"flax-beater","label":""}],"html":"<p>פשתני flax-beater  כל׳ פכ״ו מ״ח: עור הכתן עור הכתף וכו׳.</p>","notation":["ז׳"]},"40066":{"h":"כִּתֵּף","r":"KRU09917","alt":[],"source":"krupnik","glosses":[{"text":"to carry","label":"פיעל, 1"},{"text":"to load","label":"פיעל, 2"}],"html":"<p>פיעל, 1 נשא משא to carry  ירוש׳ שבי׳ פ״ח ל״ח ע״ב: מכתפי פירות.\nפיעל, 2 הטעין על הכתף to load  עיר׳ ל״ג ע״א: רבים מכתפין עליו.</p>","notation":[]},"40067":{"h":"כַּתָּף","r":"KRU09919","alt":["כַּתָּפָא"],"source":"krupnik","glosses":[{"text":"carrier, porter","label":""}],"html":"<p>נושא משא, סבל carrier, porter  תוס׳ בר׳ ב׳ ז׳: כתף אע״פ שמשאו על כתיפו הרי זה קורא; ירוש׳ שבו׳ פ״ז ל״ח ע״א: סמכון כתפייא גבי קפילייא.</p>","notation":[]},"40068":{"h":"כַּתְפָּא","r":"KRU09920","alt":[],"source":"krupnik","glosses":[{"text":"shoulder","label":""}],"html":"<p>כתף shoulder  ירוש׳ קיד׳ פ״א ס״א ע״א: מסתמיך על כתפיה.</p>","notation":["ז׳"]},"40069":{"h":"כַּתְּפִי","r":"KRU09921","alt":[],"source":"krupnik","glosses":[{"text":"name of a place","label":""}],"html":"<p>name of a place  סנה׳ ד׳ ע״ב: טט בכתפי שתים. </p>","notation":["שם מקום"]},"40070":{"h":"כתר","r":"KRU09924","alt":[],"source":"krupnik","glosses":[{"text":"to crown, to adorn","label":"הִכְתִּיר·– הפ׳"}],"html":"<p>הִכְתִּיר·– הפ׳ קישט בכתר וכדומה to crown, to adorn  ויק״ר פכ״ד: מכתירין להקב״ה שלש קדושות.</p>","notation":["Source marks no qal form"]},"40071":{"h":"כַּתַּר","r":"KRU09925","alt":[],"source":"krupnik","glosses":[{"text":"to hope for, to wait upon","label":"פַעל, אַכְתַּר אפ׳"}],"html":"<p>פַעל, אַכְתַּר אפ׳ חיכה, ציפה, קוה to hope for, to wait upon  תרג׳ יש׳ מ״ב ד׳ (ייחלו): יכתרון; מיכה ה׳ ו׳ (ייחל): מַכתר.</p>","notation":[]},"40072":{"h":"כָּתַשׁ","r":"KRU09926","alt":[],"source":"krupnik","glosses":[{"text":"to be pounded","label":"נִכְתַּשׁ נפ׳,"},{"text":"to wrestle","label":"הִתְכַּתֵּשׁ התפ׳,"}],"html":"<p>נִכְתַּשׁ נפ׳, היה כתות ונדוך to be pounded  תר׳ פ״א מ״ח: זיתים הנכתשין.\nהִתְכַּתֵּשׁ התפ׳, התגושש to wrestle  ירוש׳ פאה פ״ד י״ח ע״ב: שנים שהיו מתכתשין על העומר ובא עני אחר וחטפו מלפניהן זכה בו.</p>","notation":["Marked biblical in source"]},"40073":{"h":"כְּתַשׁ","r":"KRU09927","alt":[],"source":"krupnik","glosses":[{"text":"to crush","label":""},{"text":"to be afflicted with leprosy","label":""}],"html":"<p>1) כתת ודך to crush  תרג׳ שמ׳ כ״ז כ׳ (זית זך כתית): זיתא דכיא כתישא. אִתְכַּתַּשׁ, אִכַּתַּש  אתפ׳, 1) היה מנוגע to be afflicted with leprosy  תרג׳ תה׳ ע״ג ה׳ (ינגעו): מתכתשין. 2) עי׳ הִתְכַּתֵּשׁ. ב״ר פמ״ח: הות מכתשא עם אמתה. </p>","notation":["פ״י"]},"40074":{"h":"כִּתֵּת","r":"KRU09928","alt":["כִּתֵּת רַגְלָיו"],"source":"krupnik","glosses":[{"text":"to run one's legs for …","label":""}],"html":"<p>הרבה ללכת עד שבצקו רגליו to run one&#x27;s legs for …  ב״ב ח׳ ע״א: אלו תלמידי חכמים שמכתתים רגליהם מעיר לעיר ללמוד תורה.</p>","notation":["Marked biblical in source"]},"40075":{"h":"כַּתֵּת","r":"KRU09929","alt":[],"source":"krupnik","glosses":[{"text":"to crush","label":""},{"text":"to be crushed","label":""},{"text":"to come in contact","label":""}],"html":"<p>שיבר ופוצץ to crush  ע״ז מ״ד ע״א: בדין הוא דכתותי לא הוה צריך וכו׳. אִיכַּתֵּת אתפ׳, 1) נכתש ונדוך to be crushed  סוכה ל״א ע״ב: כתותי מיכתת וכו׳. 2) נפגש to come in contact  ב״ר פע״ח: מיכתת אנא גביהון. </p>","notation":["פַעל"]},"40076":{"h":"לֹא","r":"KRU09931","alt":[],"source":"krupnik","glosses":[{"text":"you have no right","label":""}],"html":"<p>·– לֹא הֵימֶךָ אין אתה רשאי you have no right  במ״ר פ״ד: לא הימך לומר לי ליתן ה׳ סלעים.</p>","notation":[]},"40077":{"h":"לֹא הַכֹּל","r":"KRU09932","alt":[],"source":"krupnik","glosses":[{"text":"not all depends on him","label":""}],"html":"<p>מִמֶּנוּ, לֹא כָּל הֵימֶנּוּ, לֹא כָּל כְּמִינֵיה לא הכל תלוי בו not all depends on him  ירוש׳ שבי׳ פ״ח ל״ז ע״ד: לא הכל ממנו; ב״ר פל״ח: לא כל הימנו שיבור לו; סנה׳ מ״ו ע״ב: לא כל כמיניה.</p>","notation":[]},"40078":{"h":"לֹא כָּל שֶׁכֵּן","r":"KRU09934","alt":[],"source":"krupnik","glosses":[{"text":"so much the more","label":""}],"html":"<p>על אחת כמה וכמה so much the more  בר׳ נ״ג ע״ב: לכבוד עצמו הוא עולה לכבוד שמים לא כל שכן.</p>","notation":[]},"40079":{"h":"לֹא כְלוּם","r":"KRU09935","alt":[],"source":"krupnik","glosses":[{"text":"nothing","label":""}],"html":"<p>אפס, אין nothing  דב״ר פ״א: מה אתה מוכר אמר לו לא כלום אמר לו אני שמעתי את קולך שהיית אומר הרי ארגמן ואתה אומר לא כלום.</p>","notation":[]},"40080":{"h":"לֹא כְּלָל","r":"KRU09936","alt":[],"source":"krupnik","glosses":[{"text":"nothing at all, not at all","label":""}],"html":"<p>לגמרי לא nothing at all, not at all  שבת ס״ב ע״ב: לא אמרן אלא דלא משא ידיה כלל.</p>","notation":[]},"40081":{"h":"לֹא מַעֲלֶה וְלֹא מוֹרִיד","r":"KRU09937","alt":[],"source":"krupnik","glosses":[{"text":"has no effect or influence","label":""}],"html":"<p>אין לו שום ערך והשפעה has no effect or influence  גיט׳ נ״ב ע״א: דברי חלומות לא מעלין ולא מורידין.</p>","notation":[]},"40082":{"h":"לֹא מִפִּיו אָנוּ חַיִּים","r":"KRU09938","alt":[],"source":"krupnik","glosses":[{"text":"we do not go by his evidence","label":""}],"html":"<p>אין אנו סומכים עליו we do not go by his evidence  כת׳ פ״א מ״ו: לא מפיה אנו חיין.</p>","notation":[]},"40083":{"h":"לֹא תַעֲשֶׂה","r":"KRU09939","alt":[],"source":"krupnik","glosses":[{"text":"a prohibitory law","label":""}],"html":"<p>מצוה של איסור ושלילה בנגוד למצוה חיובית של קום ועשה a prohibitory law  מכות י״ד ע״ב: כל לא תעשה שקדמו עשה לוקין עליו.</p>","notation":[]},"40084":{"h":"לָא","r":"KRU09940","alt":[],"source":"krupnik","glosses":[{"text":"name of an Amora","label":""}],"html":"<p>שם אמורא name of an Amora  ירוש׳ סנה׳ פ״ו כ״ג ע״ד: ר׳ לא.</p>","notation":["Marked biblical in source"]},"40085":{"h":"לֹא סוֹף דָּבָר","r":"KRU09941","alt":[],"source":"krupnik","glosses":[{"text":"not only","label":""}],"html":"<p>לא זה בלבד, לא רק not only  ירוש׳ שבת פ״ד ו׳ ע״ד: לא סוף דבר לחין אפי׳ יבשין שנתלחלחו.</p>","notation":[]},"40086":{"h":"לָא סַגְיָא","r":"KRU09942","alt":[],"source":"krupnik","glosses":[{"text":"it is out of the question","label":""}],"html":"<p>אי אפשר, מן הנמנע it is out of the question  תמיד ל״ב ע״א: לא סגיא דלא אזלינא.</p>","notation":[]},"40087":{"h":"לָא שְׁנָא","r":"KRU09943","alt":[],"source":"krupnik","glosses":[{"text":"there is no difference","label":""}],"html":"<p>אין שום הבדל there is no difference  פס׳ י׳ ע״ב: או דלמא לא שנא.</p>","notation":[]},"40088":{"h":"לָאגְרָא","r":"KRU09944","alt":[],"source":"krupnik","glosses":[{"text":"a man’s name","label":""}],"html":"<p>a man’s name  קהל״ר ז׳ י״א: יצתה בת קול ואמרה אף לאגרה קצרא מזומן לחיי העולם הבא. </p>","notation":["שם איש"]},"40089":{"h":"לַאו","r":"KRU09945","alt":[],"source":"krupnik","glosses":[{"text":"no, not","label":"1"},{"text":"a prohibitory law","label":"2"}],"html":"<p>1  no, not  גיט׳ פ״ז מ״א: אם אמר על לאו לאו ועל הן הן וכו׳; שמו״ר פ״ה: אמרו לו רבך לאו כהן הוא.\n2  a prohibitory law  תוס׳ חול׳ ז׳ י׳: חייבין עליו משום שני לאוין משום חלב ומשום חי.</p>","notation":[]},"40090":{"h":"לַאו דַּוְקָא","r":"KRU09946","alt":[],"source":"krupnik","glosses":[{"text":"not exactly","label":""}],"html":"<p>לא בדיוק not exactly  גיט׳ מ״ד ע״א: דוקא או לאו דוקא.</p>","notation":[]},"40091":{"h":"לַאו שֶׁנִּיתַּק לַעֲשֵׁה","r":"KRU09947","alt":[],"source":"krupnik","glosses":[{"text":"a prohibitive law the transgression of which must be repaired by a succeeding act","label":""},{"text":"without","label":""},{"text":"does it not mean that","label":""}],"html":"<p>מצות לא תעשה שיש בה קום עשה a prohibitive law the transgression of which must be repaired by a succeeding act  חול׳ קמ״א ע״ב: לאו שניתק לעשה לוקין עליו. בְּלַאו בלא without  ב״ק י׳ ע״א: בלאו איהו. מַאי לַאו וכי אין הדבר כך does it not mean that  נדה ה׳ ע״א: מאי לאו חד לפני תשמיש וחד לאחר תשמיש לא אידי ואידי לאחר תשמיש. </p>","notation":[]},"40092":{"h":"לְאוֹרָעָא","r":"KRU09948","alt":[],"source":"krupnik","glosses":[{"text":"to meet","label":""}],"html":"<p>לקראת to meet  תרג׳ מש׳ ז׳ י׳ (לקראת): לאורעא.</p>","notation":["תה״פ"]},"40093":{"h":"לְאִיטוֹר","r":"KRU09958","alt":["לְאִיטָר"],"source":"krupnik","glosses":[{"text":"rhetor, advocate","label":""}],"html":"<p>דברן, מליץ rhetor, advocate  ספרא דב׳ שמ״ג: משל למה הדבר דומה ללאיטור שהיה עומד על הבימה (ילק׳ שם תתקנ״א: ללאיטר).</p>","notation":[]},"40094":{"h":"לְאַלְתַּר","r":"KRU09962","alt":[],"source":"krupnik","glosses":[{"text":"at once","label":""}],"html":"<p>תיכף ומיד at once  ר״ה ט״ז ע״ב: צדיקים גמורים נכתבין ונחתמין לאלתר לחיים.</p>","notation":[]},"40095":{"h":"לאָן","r":"KRU09965","alt":[],"source":"krupnik","glosses":[{"text":"whither","label":""}],"html":"<p>ומה״י, להיכן, לאין whither  אבות פ״ג מ״א: דע מאין באת ולאן אתה הולך.</p>","notation":["מה״ש"]},"40096":{"h":"לְאַפּוֹקֵי","r":"KRU09967","alt":[],"source":"krupnik","glosses":[{"text":"with the exception of","label":""}],"html":"<p>להוציא, מלבד with the exception of  נד׳ מ״א ע״א: לאפוקי מאי לאפוקי הא דתניא וכו׳.</p>","notation":["תה״פ"]},"40097":{"h":"לְאַפְרַשׁ","r":"KRU09968","alt":[],"source":"krupnik","glosses":[{"text":"forever","label":""}],"html":"<p>לעולם, לנצח forever  תרג׳ ש״ב ב׳ כ״ו (הלנצח תאכל חרב): הלאפרש תקטול חרבא.</p>","notation":["תה״פ"]},"40098":{"h":"לֵב","r":"KRU09970","alt":[],"source":"krupnik","glosses":[{"text":"bosom","label":""}],"html":"<p>חזה bosom  סוטה פ״א מ״ה: וכהן אוחז בבגדיה אם נקרעו נקרעו וכו׳ עד שהוא מגלה את לבה.</p>","notation":["Marked biblical in source"]},"40099":{"h":"לִבָּא","r":"KRU09972","alt":[],"source":"krupnik","glosses":[{"text":"heart","label":""}],"html":"<p>לב heart  תרג׳ דהי״א י״ב ל״ג (בלא לב ולב): בלא לבא ולבא. ועי׳ לִיבָּא.</p>","notation":["ז׳"]},"40100":{"h":"לַבָּא","r":"KRU09973","alt":[],"source":"krupnik","glosses":[{"text":"in future","label":""}],"html":"<p>לעתיד in future  ירוש׳ תר׳ פ״א מ׳ ע״ב: מיכן ולבא.</p>","notation":["Equivalent spelling: לְהַבָּא"]},"40101":{"h":"לָבַב","r":"KRU09975","alt":[],"source":"krupnik","glosses":[{"text":"to be tied around","label":""}],"html":"<p>עי׳ לָבוּב. נִלְבַּב נפ׳, נכרך ונקשר to be tied around  ירוש׳ שבת פ״י י״ב ע״ד: העושה פסיקא לילבב. </p>","notation":[]},"40102":{"h":"לִבֵּב","r":"KRU09976","alt":[],"source":"krupnik","glosses":[{"text":"to encourage","label":""}],"html":"<p>פיעל·– אימץ את הלב to encourage  ב״ר פע״ז: והיה המלך נוטל את בנו ומלבבו בארי.</p>","notation":[]},"40103":{"h":"לְבַדבִּלְבַד","r":"KRU09978","alt":[],"source":"krupnik","glosses":[{"text":"only","label":""},{"text":"but only, provided","label":""}],"html":"<p>תה״פ, רק only  ב״מ פ״ז מ״א: שאין לכם עלי אלא פת וקטנית בלבד. וּבִלְבַד בתנאי, רק אם but only, provided  שבת פכ״ב מ״ג: שובר אדם את החבית לאכול הימנה גרוגרות ובלבד שלא יתכוין לעשות כלי. </p>","notation":["Marked biblical in source"]},"40104":{"h":"לֶבֶד","r":"KRU09979","alt":["לִבְדָּא"],"source":"krupnik","glosses":[{"text":"felt","label":""}],"html":"<p>צמר כבוש felt  תוס׳ כל׳ ב״ב ה׳ ג׳: העושה חלוק מן הלבד וכו׳; ירוש׳ בר׳ פ״ב ה׳ ע״א: אתעבוד זבין לבדין למיינוקי.</p>","notation":[]},"40105":{"h":"לַבַּדָּא","r":"KRU09980","alt":[],"source":"krupnik","glosses":[{"text":"the hairy side of cloth","label":""}],"html":"<p>הצד השעיר של הבגד the hairy side of cloth  תרג׳ יב״ע ויק׳ י״ג נ״ה (בקרחתו או בגבחתו): ברדדיה או בלבדיה.</p>","notation":["ז׳"]},"40106":{"h":"לִבָּה","r":"KRU09982","alt":[],"source":"krupnik","glosses":[{"text":"to fan the flame","label":"פיעל,"},{"text":"to flame up","label":"נִתְלַבָּה נתפ׳,"}],"html":"<p>פיעל, נשב והעלה אש to fan the flame  ב״ק נ״ט ע״ב: שמסר לו גחלת וליבה.\nנִתְלַבָּה נתפ׳, נתלהט to flame up  שבת ל״ז ע״א: קטמה ונתלבתה.</p>","notation":[]},"40107":{"h":"לָבוּב","r":"KRU09983","alt":[],"source":"krupnik","glosses":[{"text":"tied","label":"1"},{"text":"perforated","label":"2"}],"html":"<p>1 מקושר tied  שבת פ״ה מ״ב: זכרין יוצאין לבובין.\n2 מנוקב perforated  ע״ז פ״ב מ״ג: עורות לבובין.</p>","notation":["ת׳"]},"40108":{"h":"לָבוּד","r":"KRU09984","alt":[],"source":"krupnik","glosses":[{"text":"solid, connected","label":""}],"html":"<p>מחובר, מעור אחד solid, connected  סוכה ט״ז ע״ב: כל פחות משלשה סמוך לדופן כלבוד דמי.</p>","notation":["ת׳"]},"40109":{"h":"לִבּוּי","r":"KRU09985","alt":[],"source":"krupnik","glosses":[{"text":"fanning a flame","label":""}],"html":"<p>העלאת אש ע״י נשיבה fanning a flame  ב״ק ס׳ ע״א: ליבה ולבתה הרוח אם יש בלבויו כדי ללבותה וכו׳.</p>","notation":["ז׳"]},"40110":{"h":"לִבּוּנָא","r":"KRU09987","alt":[],"source":"krupnik","glosses":[{"text":"foundation","label":""}],"html":"<p>יסוד foundation  שבת ק״ד ע״א: שיקרא אחדא כרעא קאי ואמת מלבן לבוניה.</p>","notation":["נ׳"]},"40111":{"h":"לְבוּנְתָּא","r":"KRU09988","alt":[],"source":"krupnik","glosses":[{"text":"frankincense","label":""}],"html":"<p>לבונה frankincense  תרג׳ שמ׳ ל׳ ל״ד (לבונה זכה): לבונתא דכיתא.</p>","notation":["נ׳"]}};
